class Splash:
    def __init__(self, root):
        self.win=tk.Toplevel(root); self.win.overrideredirect(True)
        self.win.configure(bg=TERM_BG)
        w,h=500,300
        sw=root.winfo_screenwidth(); sh=root.winfo_screenheight()
        self.win.geometry(f"{w}x{h}+{(sw-w)//2}+{(sh-h)//2}")
        self.win.lift(); self.win.attributes("-topmost",True)
        tk.Label(self.win,text="⚡",font=("Segoe UI Emoji",48),bg=TERM_BG,fg=TERM_YLW).pack(pady=(28,0))
        tk.Label(self.win,text="ShikaNet",font=(FONT_MONO,16,"bold"),
                 bg=TERM_BG,fg=TERM_PUR).pack()
        tk.Label(self.win,text=f"v{APP_VERSION}  ·  Cisco · Juniper · Arista · NX-OS",
                 font=(FONT_MONO,9),bg=TERM_BG,fg=TERM_GRY).pack(pady=(4,18))
        self.pb=ttk.Progressbar(self.win,bootstyle="success-striped",
                                length=360,mode="determinate",maximum=100)
        self.pb.pack(pady=(0,8))
        self.lbl=tk.Label(self.win,text="Starting…",font=(FONT_MONO,8),bg=TERM_BG,fg=TERM_GRY)
        self.lbl.pack()
        tk.Label(self.win,text=f"© {datetime.now().year} ShikaNet",
                 font=(FONT_MONO,7),bg=TERM_BG,fg=TERM_GRY).pack(side=BOTTOM,pady=8)
    def update(self,pct,msg):
        self.pb["value"]=pct; self.lbl.config(text=msg); self.win.update()
    def close(self): self.win.destroy()

