# DEVICE DIALOG  (Add / Edit  —  includes jump host + console via AP)
# ─────────────────────────────────────────────────────────────────────────────
class DeviceDlg(tk.Toplevel):
    def __init__(self, parent, title="Add Device", prefill=None):
        super().__init__(parent); self.title(title)
        self.resizable(False,False); self.grab_set(); self.result=None
        pf=prefill or {}; pad=dict(padx=10,pady=4)

        # ── Notebook inside dialog ────────────────────────────────────────────
        nb=ttk.Notebook(self,bootstyle="primary")
        nb.pack(fill=BOTH,expand=True,padx=8,pady=8)

        # Tab 1: Target device
        tf=ttk.Frame(nb,padding=8); nb.add(tf,text="  Target Device  ")
        rows=[("Name (label)",pf.get("_name",""),""),
              ("Host / IP",   pf.get("host",""),""),
              ("Username",    pf.get("username",""),""),
              ("Password",    pf.get("password",""),"*"),
              ("Port",        str(pf.get("port",22)),""),
              ("Key File",    pf.get("key_file",""),"")]
        self.ent={}
        for i,(lbl,val,show) in enumerate(rows):
            ttk.Label(tf,text=lbl,font=(FONT_MONO,9,"bold")).grid(row=i,column=0,sticky=W,**pad)
            e=ttk.Entry(tf,font=(FONT_MONO,10),show=show,width=36)
            e.insert(0,val); e.grid(row=i,column=1,**pad); self.ent[lbl]=e
        ttk.Button(tf,text="…",width=3,command=self._browse,
                   bootstyle="secondary-outline").grid(row=5,column=2,padx=(0,8))
        ttk.Label(tf,text="Device Type",font=(FONT_MONO,9,"bold")).grid(row=6,column=0,sticky=W,**pad)
        self.dtype=tk.StringVar(value=pf.get("device_type","cisco_ios"))
        ttk.Combobox(tf,textvariable=self.dtype,values=DEVICE_TYPES,
                     state="readonly",font=(FONT_MONO,10),width=34).grid(row=6,column=1,**pad)
        self.fast=tk.BooleanVar(value=pf.get("fast_cli",False))
        ttk.Checkbutton(tf,text="fast_cli",variable=self.fast,
                        bootstyle="primary").grid(row=7,column=1,sticky=W,padx=10)

        # Tab 2: Jump host (SSH proxy through AP / bastion)
        jf=ttk.Frame(nb,padding=8); nb.add(jf,text="  Jump Host / AP  ")
        ttk.Label(jf,text="Leave blank for direct SSH connection.",
                  font=(FONT_MONO,8),bootstyle="secondary").grid(row=0,column=0,columnspan=2,sticky=W,**pad)
        jrows=[("Jump Host IP", pf.get("jump_host",""),""),
               ("Jump Username",pf.get("jump_username",""),""),
               ("Jump Password",pf.get("jump_password",""),"*"),
               ("Jump Port",    str(pf.get("jump_port",22)),"")]
        self.jent={}
        for i,(lbl,val,show) in enumerate(jrows):
            ttk.Label(jf,text=lbl,font=(FONT_MONO,9,"bold")).grid(row=i+1,column=0,sticky=W,**pad)
            e=ttk.Entry(jf,font=(FONT_MONO,10),show=show,width=36)
            e.insert(0,val); e.grid(row=i+1,column=1,**pad); self.jent[lbl]=e
        ttk.Label(jf,text="Jump Dev Type",font=(FONT_MONO,9,"bold")).grid(row=5,column=0,sticky=W,**pad)
        self.jtype=tk.StringVar(value=pf.get("jump_device_type","cisco_ios"))
        ttk.Combobox(jf,textvariable=self.jtype,values=DEVICE_TYPES,
                     state="readonly",font=(FONT_MONO,10),width=34).grid(row=5,column=1,**pad)

        # Tab 3: Console via AP (telnet/serial hop)
        cf=ttk.Frame(nb,padding=8); nb.add(cf,text="  Console via AP  ")
        ttk.Label(cf,text="SSH to AP first, then console into switch via its console server port.",
                  font=(FONT_MONO,8),bootstyle="warning",wraplength=420).grid(
            row=0,column=0,columnspan=2,sticky=W,**pad)
        con_rows=[("AP Host",        pf.get("console_ap_host",""),""),
                  ("AP Username",    pf.get("console_ap_user",""),""),
                  ("AP Password",    pf.get("console_ap_pass",""),"*"),
                  ("Console Command",pf.get("console_cmd","telnet 0"),""),
                  ("Device Password",pf.get("console_dev_pass",""),"*")]
        self.cent={}
        for i,(lbl,val,show) in enumerate(con_rows):
            ttk.Label(cf,text=lbl,font=(FONT_MONO,9,"bold")).grid(row=i+1,column=0,sticky=W,**pad)
            e=ttk.Entry(cf,font=(FONT_MONO,10),show=show,width=36)
            e.insert(0,val); e.grid(row=i+1,column=1,**pad); self.cent[lbl]=e
        ttk.Label(cf,
                  text="Console Command example:\n"
                       "  'telnet 0'  — if AP has a built-in console server port\n"
                       "  'ssh -l admin 192.168.1.5'  — SSH from AP to switch",
                  font=(FONT_MONO,8),bg=TERM_BG,fg=TERM_GRY,justify=LEFT).grid(
            row=6,column=0,columnspan=2,sticky=W,padx=12,pady=(8,0))

        # Buttons
        bf=ttk.Frame(self); bf.pack(pady=10)
        ttk.Button(bf,text="Save",        command=self._save,          bootstyle="success",          width=12).pack(side=LEFT,padx=6)
        ttk.Button(bf,text="🔍 Test Conn", command=self._test_in_dialog, bootstyle="info-outline",    width=13).pack(side=LEFT,padx=6)
        ttk.Button(bf,text="Cancel",       command=self.destroy,         bootstyle="secondary-outline",width=12).pack(side=LEFT,padx=6)
        self.ent["Name (label)"].focus_set()
        self.bind("<Return>",lambda _:self._save())

    def _browse(self):
        fn=filedialog.askopenfilename(title="SSH Key",filetypes=[("Key","*.pem *.key *"),("All","*.*")])
        if fn: self.ent["Key File"].delete(0,"end"); self.ent["Key File"].insert(0,fn)

    def _save(self):
        name=self.ent["Name (label)"].get().strip()
        host=self.ent["Host / IP"].get().strip()
        user=self.ent["Username"].get().strip()
        if not all([name,host,user]):
            messagebox.showwarning("Missing","Name, Host and Username are required.",parent=self); return
        _port_raw = self.ent["Port"].get().strip()
        try:
            port = int(_port_raw)
            if not (1 <= port <= 65535):
                raise ValueError(f"port {port} out of range")
        except ValueError:
            messagebox.showwarning(
                "Invalid Port",
                f"Port value '{_port_raw}' is not a valid TCP port (1–65535).\n"
                "Defaulting to 22.",
                parent=self,
            )
            port = 22
            self.ent["Port"].delete(0, "end")
            self.ent["Port"].insert(0, "22")
        _jp_raw = self.jent["Jump Port"].get().strip()
        try:
            jp = int(_jp_raw)
            if not (1 <= jp <= 65535):
                raise ValueError(f"jump port {jp} out of range")
        except ValueError:
            jp = 22
        self.result={
            "_name":name,"device_type":self.dtype.get(),
            "host":host,"username":user,
            "password":self.ent["Password"].get().strip(),
            "port":port,"fast_cli":self.fast.get(),
            "key_file":self.ent["Key File"].get().strip(),
            "jump_host":self.jent["Jump Host IP"].get().strip(),
            "jump_username":self.jent["Jump Username"].get().strip(),
            "jump_password":self.jent["Jump Password"].get().strip(),
            "jump_port":jp,"jump_device_type":self.jtype.get(),
            "console_ap_host":self.cent["AP Host"].get().strip(),
            "console_ap_user":self.cent["AP Username"].get().strip(),
            "console_ap_pass":self.cent["AP Password"].get().strip(),
            "console_cmd":self.cent["Console Command"].get().strip(),
            "console_dev_pass":self.cent["Device Password"].get().strip(),
        }
        self.destroy()

    def _test_in_dialog(self):
        """Quick TCP reachability test from within the Add/Edit Device dialog."""
        import socket as _sock
        host = self.ent["Host / IP"].get().strip()
        try:
            port = int(self.ent["Port"].get())
        except ValueError:
            port = 22
        if not host:
            messagebox.showwarning("Missing", "Enter a Host/IP address first.", parent=self)
            return
        try:
            with _sock.create_connection((host, port), timeout=5):
                pass
            messagebox.showinfo(
                "TCP OK",
                f"TCP connection to {host}:{port} succeeded.\n"
                "SSH credentials will be verified when you Connect.",
                parent=self,
            )
        except OSError as _e:
            messagebox.showerror(
                "Connection Failed",
                f"Cannot reach {host}:{port}\n\nError: {_e}\n\n"
                "Check the IP address, port, and network path.",
                parent=self,
            )



# ─────────────────────────────────────────────────────────────────────────────
# SIDEBAR NAVIGATION  —  replaces ttk.Notebook to fix ~24-tab overflow (Fix 2)
# Drop-in replacement: supports .add(), .insert(), .select(), .index(), .tab()
# ─────────────────────────────────────────────────────────────────────────────
class SidebarNotebook(ttk.Frame):
    """Left-sidebar tab navigator that groups tabs into labelled categories.

    Inherits from ttk.Frame so tkinter always finds the .tk interpreter handle
    when tab frames are created with SidebarNotebook as their master.
    The public API (.add, .insert, .select, .index, .tab) is compatible with
    ttk.Notebook — no other code needs to change.
    """

    _GROUPS = [
        ("CORE",        ["Commands","Custom CLI","Config Write","Troubleshoot"]),
        ("DATA",        ["Backup","Diff","Monitoring","Inventory","Audit"]),
        ("NETWORK",     ["Multi-Device","Discovery","Topology"]),
        ("ANALYSIS",    ["Compliance","Firmware","Reports","Templates"]),
        ("DEVICES",     ["Devices","Email"]),
        ("SYSTEM",      ["Alerts","AI","Plugins","Settings","Users","Help"]),
        ("OTHER",       []),
    ]

    def __init__(self, parent):
        super().__init__(parent)          # ← makes self a real ttk.Frame widget
        self.pack(fill=BOTH, expand=True)

        self._tabs    = []   # [(label_text, frame), …]
        self._current = 0
        self._header_indices = set()
        self._lb_to_tab      = {}

        # ── Left sidebar ──────────────────────────────────────────────────
        sidebar = ttk.Frame(self, width=195)
        sidebar.pack(side=LEFT, fill=Y)
        sidebar.pack_propagate(False)

        ttk.Label(sidebar, text="NAVIGATION",
                  font=(FONT_MONO, 8, "bold"),
                  bootstyle="secondary").pack(anchor=W, padx=10, pady=(10, 4))

        lbf = ttk.Frame(sidebar)
        lbf.pack(fill=BOTH, expand=True, padx=4, pady=(0, 6))

        self._lb = tk.Listbox(
            lbf,
            font=(FONT_MONO, 9),
            bg=TERM_BG, fg=TERM_TEXT,
            selectbackground=TERM_PUR,
            selectforeground="#000",
            relief="flat", bd=0,
            activestyle="none",
        )
        _sc = ttk.Scrollbar(lbf, orient=VERTICAL,
                             command=self._lb.yview,
                             bootstyle="secondary-round")
        self._lb.configure(yscrollcommand=_sc.set)
        self._lb.pack(side=LEFT, fill=BOTH, expand=True)
        _sc.pack(side=RIGHT, fill=Y)
        self._lb.bind("<<ListboxSelect>>", self._on_select)

        ttk.Separator(self, orient=VERTICAL).pack(side=LEFT, fill=Y)

        # ── Content area ──────────────────────────────────────────────────
        self._content = ttk.Frame(self)
        self._content.pack(side=LEFT, fill=BOTH, expand=True)

    # ── Helpers ───────────────────────────────────────────────────────────
    def _group_for(self, label):
        clean = label.strip()
        for grp, keywords in self._GROUPS:
            for kw in keywords:
                if kw.lower() in clean.lower():
                    return grp
        return "OTHER"

    def _rebuild_lb(self):
        self._lb.delete(0, "end")
        self._header_indices.clear()
        self._lb_to_tab.clear()
        last_group = None
        lb_idx = 0
        for tab_idx, (label, _) in enumerate(self._tabs):
            grp = self._group_for(label)
            if grp != last_group:
                self._lb.insert("end", f"  {grp}")
                self._lb.itemconfig(lb_idx, fg=TERM_PUR,
                                    selectbackground=TERM_BG,
                                    selectforeground=TERM_PUR)
                self._header_indices.add(lb_idx)
                lb_idx += 1
                last_group = grp
            import re as _re
            clean = _re.sub(r"^[\s\W]+", "", label).strip()
            self._lb.insert("end", f"    {clean}")
            self._lb_to_tab[lb_idx] = tab_idx
            lb_idx += 1
        self._select_in_lb(self._current)

    def _select_in_lb(self, tab_idx):
        self._lb.selection_clear(0, "end")
        for lb_i, t_i in self._lb_to_tab.items():
            if t_i == tab_idx:
                self._lb.selection_set(lb_i)
                self._lb.see(lb_i)
                break

    # ── Public API (ttk.Notebook–compatible) ──────────────────────────────
    def _show_tab(self, idx):
        """Place only the active frame; remove all others from geometry management."""
        for i, (_, f) in enumerate(self._tabs):
            if i == idx:
                f.place(in_=self._content, x=0, y=0, relwidth=1, relheight=1)
            else:
                f.place_forget()

    def add(self, frame, text="", **kw):
        self._tabs.append((text.strip(), frame))
        # Only the very first tab is shown immediately; others stay unmanaged.
        if len(self._tabs) == 1:
            frame.place(in_=self._content, x=0, y=0, relwidth=1, relheight=1)
            self._current = 0
        self._rebuild_lb()

    def insert(self, pos, frame, text="", **kw):
        pos = int(pos)
        self._tabs.insert(pos, (text.strip(), frame))
        if pos <= self._current and len(self._tabs) > 1:
            self._current += 1
        self._rebuild_lb()
        # Inserting at position 0 (Dashboard) should make it the visible tab.
        if pos == 0:
            self.select(0)

    def select(self, idx):
        if isinstance(idx, str):
            return
        try:
            idx = int(idx)
        except (TypeError, ValueError):
            return
        if not (0 <= idx < len(self._tabs)):
            return
        self._current = idx
        self._show_tab(idx)       # only one frame placed at a time → no resize jank
        self._select_in_lb(idx)

    def index(self, what):
        if what == "end":
            return len(self._tabs)
        if what == "current":
            return self._current
        return 0

    def tab(self, idx, **kw):
        if "text" in kw and 0 <= idx < len(self._tabs):
            _, frame = self._tabs[idx]
            self._tabs[idx] = (kw["text"].strip(), frame)
            self._rebuild_lb()

    def _on_select(self, event=None):
        sel = self._lb.curselection()
        if not sel:
            return
        lb_i = sel[0]
        if lb_i in self._header_indices:
            self._lb.selection_clear(0, "end")
            self._select_in_lb(self._current)
            return
        tab_idx = self._lb_to_tab.get(lb_i)
        if tab_idx is not None:
            self.select(tab_idx)

