    # ═════════════════════════════════════════════════════════════════════════
    # GUI HELPERS
    # ═════════════════════════════════════════════════════════════════════════
    def _shdr(self, p, t):
        ttk.Label(p,text=t,font=(FONT_MONO,10,"bold"),bootstyle="primary").pack(anchor=W,pady=(0,8))
    def _hdr(self, p, t):
        ttk.Label(p,text=t,font=(FONT_MONO,8,"bold"),bootstyle="secondary").pack(anchor=W,pady=(0,4))

    def _ff(self, parent, label, ph):
        ttk.Label(parent,text=label,font=(FONT_MONO,8,"bold"),
                  bootstyle="secondary").pack(anchor=W,pady=(5,0))
        e=ttk.Entry(parent,font=(FONT_MONO,10))
        e.insert(0,ph); e.config(foreground="gray")
        e.bind("<FocusIn>", lambda ev,p=ph,en=e: (en.delete(0,"end"),en.config(foreground=TERM_TEXT)) if en.get()==p else None)
        e.bind("<FocusOut>",lambda ev,p=ph,en=e: (en.insert(0,p),en.config(foreground="gray")) if not en.get() else None)
        e.pack(fill=X,pady=(2,2),ipady=4)
        return e

    def _fv(self, e, ph):
        v=e.get().strip(); return "" if v==ph else v

    def _mkbox(self, parent):
        if not hasattr(self,"_all_boxes"): self._all_boxes=[]
        c=ttk.Frame(parent); c.pack(fill=BOTH,expand=True)
        box=tk.Text(c,font=(FONT_MONO,self._font_sz),bg=TERM_BG,fg=TERM_TEXT,
                    insertbackground=TERM_TEXT,relief="flat",bd=0,wrap="word",
                    padx=8,pady=6,selectbackground=TERM_GRY,selectforeground=TERM_TEXT,
                    maxundo=0,state="disabled")
        sc=ttk.Scrollbar(c,orient=VERTICAL,command=box.yview,bootstyle="secondary-round")
        box.configure(yscrollcommand=sc.set)
        box.pack(side=LEFT,fill=BOTH,expand=True); sc.pack(side=RIGHT,fill=Y)
        for tag,fg,extra in [
            ("hdr", TERM_PUR,{"font":(FONT_MONO,self._font_sz,"bold")}),
            ("ok",  TERM_GRN,{}),("err",TERM_RED,{}),
            ("inf", TERM_BLU,{}),("div",TERM_GRY,{}),
            ("wrn", TERM_YLW,{}),("cyn",TERM_CYN,{}),
            ("hl",  "#000",  {"background":TERM_YLW}),
            ("add", TERM_GRN,{}),("rem",TERM_RED,{}),
        ]:
            box.tag_config(tag,foreground=fg,**extra)
        self._all_boxes.append(box)
        return box

    def _search(self, parent, box):
        sf=ttk.Frame(parent); sf.pack(fill=X,pady=(4,0))
        ttk.Label(sf,text="🔍",font=(FONT_MONO,9),bootstyle="secondary").pack(side=LEFT,padx=(0,3))
        se=ttk.Entry(sf,font=(FONT_MONO,9),width=28); se.pack(side=LEFT,padx=(0,4),ipady=2)
        rc=ttk.Label(sf,text="",font=(FONT_MONO,8),bootstyle="secondary"); rc.pack(side=LEFT,padx=4)
        def do(*_):
            box.tag_remove("hl","1.0","end")
            q=se.get().strip()
            if not q: rc.config(text=""); return
            idx="1.0"; n=0
            while True:
                pos=box.search(q,idx,nocase=True,stopindex="end")
                if not pos: break
                box.tag_add("hl",pos,f"{pos}+{len(q)}c"); idx=f"{pos}+{len(q)}c"; n+=1
            rc.config(text=f"{n} match{'es'if n!=1 else''}")
            if n:
                first=box.search(q,"1.0",nocase=True,stopindex="end")
                if first: box.see(first)
        se.bind("<Return>",do); se.bind("<KeyRelease>",do)
        ttk.Button(sf,text="✕",width=3,bootstyle="secondary-outline",
                   command=lambda:(se.delete(0,"end"),do())).pack(side=LEFT,padx=2)
        return se

    def _write(self, box, text, tag=None):
        box.configure(state="normal")
        if tag: box.insert("end",text,tag)
        else:   box.insert("end",text)
        lines=int(box.index("end-1c").split(".")[0])
        if lines>MAX_LINES: box.delete("1.0",f"{lines-MAX_LINES}.0")
        box.see("end"); box.configure(state="disabled")

    def _clr(self, box):
        box.configure(state="normal"); box.delete("1.0","end"); box.configure(state="disabled")

    def _setbar(self, t): self.bar.config(text=f"  {t}")

    def _mark_unsaved(self):
        self._unsaved=True; self.unsaved_lbl.config(text="● Unsaved session data")
    def _mark_saved(self):
        self._unsaved=False; self.unsaved_lbl.config(text="")

    def _set_status(self, on, name=""):
        if on:
            self.badge.config(text=f"◉  {name}",bootstyle="success")
            self.btn_conn.config(state=DISABLED)
            self.btn_disc.config(state=NORMAL)
            self.btn_save.config(state=NORMAL)
            for b in self.cmd_btns: b.config(state=NORMAL)
            self.btn_all.config(state=NORMAL)
            self.btn_hc.config(state=NORMAL)
            self.btn_inv.config(state=NORMAL)
            self.nb.tab(0,text=f" 📡 {name} ")
        else:
            self.badge.config(text="◉  Disconnected",bootstyle="danger")
            self.btn_conn.config(state=NORMAL)
            self.btn_disc.config(state=DISABLED)
            self.btn_save.config(state=DISABLED)
            for b in self.cmd_btns: b.config(state=DISABLED)
            self.btn_all.config(state=DISABLED)
            self.btn_hc.config(state=DISABLED)
            self.btn_inv.config(state=DISABLED)
            self.uptime_lbl.config(text="")
            self._t0=None
            self.nb.tab(0,text="  📡  Commands  ")

    def _set_theme(self, t):
        self._theme = t
        ttk.Style().theme_use(t)
        self._setbar(f"Theme: {t}")
        # Persist theme so next launch restores it
        try:
            db_set_setting("theme", t)
        except Exception:
            pass
        # ── Adjust terminal box colours for light vs dark themes (Fix 10) ─
        _LIGHT = {"flatly","litera","minty","pulse","sandstone","united","yeti",
                  "morph","journal","lumen","simplex","sketchy","spacelab",
                  "cerulean","cosmo"}
        global TERM_BG, TERM_TEXT, TERM_GRY
        if t in _LIGHT:
            TERM_BG   = "#f8f9fa"
            TERM_TEXT = "#212529"
            TERM_GRY  = "#6c757d"
        else:
            TERM_BG   = "#1e1e2e"
            TERM_TEXT = "#cdd6f4"
            TERM_GRY  = "#585b70"
        for box in getattr(self, "_all_boxes", []):
            try:
                box.configure(bg=TERM_BG, fg=TERM_TEXT)
                box.tag_config("div", foreground=TERM_GRY)
            except Exception:
                pass

    def _set_font(self, sz):
        self._font_sz=sz
        for box in self._all_boxes:
            try: box.configure(font=(FONT_MONO,sz))
            except: pass
        self._setbar(f"Font size: {sz}pt")

    def _clear_active(self):
        mapping={0:self.cmd_out,1:self.cli_out,2:self.cfg_out,
                 3:self.ts_out,4:self.bak_out,6:self.mon_out}
        t=self.nb.index("current")
        if t in mapping:
            if messagebox.askyesno("Clear Output",
                    "Clear all output in this panel?\nThis cannot be undone."):
                self._clr(mapping[t])

    def _focus_search(self):
        pass  # search bars focus via keyboard naturally

    def _copy_out(self):
        mapping={0:self.cmd_out,1:self.cli_out,2:self.cfg_out,
                 3:self.ts_out,4:self.bak_out,6:self.mon_out,10:self.em_out}
        box=mapping.get(self.nb.index("current"))
        if not box: self._setbar("Copy not available on this tab."); return
        txt=box.get("1.0","end").strip()
        if txt:
            self.root.clipboard_clear(); self.root.clipboard_append(txt)
            self._setbar(f"Copied {len(txt):,} characters to clipboard.")
        else: self._setbar("Nothing to copy.")

    # ─── UPTIME ──────────────────────────────────────────────────────────────
    def _start_uptime(self):
        def tick():
            if self._t0:
                e=int(time.time()-self._t0); h,r=divmod(e,3600); m,s=divmod(r,60)
                self.uptime_lbl.config(text=f"Session: {h:02d}:{m:02d}:{s:02d}")
            self.root.after(1000,tick)
        tick()

    # ─── NOTES ───────────────────────────────────────────────────────────────
    def _notes_dlg(self):
        win=tk.Toplevel(self.root); win.title("Session Notes")
        win.geometry("620x420"); win.grab_set(); win.configure(bg=TERM_BG)
        ttk.Label(win,text="Session Notes  (saved with session log)",
                  font=(FONT_MONO,9),bootstyle="secondary").pack(anchor=W,padx=10,pady=(10,4))
        t=tk.Text(win,font=(FONT_MONO,10),bg=TERM_BG,fg=TERM_TEXT,
                  insertbackground=TERM_TEXT,relief="flat",bd=0,padx=8,pady=6)
        t.pack(fill=BOTH,expand=True,padx=10,pady=(0,8))
        t.insert("1.0",self._notes)
        def save():
            self._notes=t.get("1.0","end").strip(); self._mark_unsaved(); win.destroy()
        ttk.Button(win,text="Save Notes",command=save,bootstyle="success").pack(pady=(0,10))


    # ═════════════════════════════════════════════════════════════════════════
    # CONNECTION
    # ═════════════════════════════════════════════════════════════════════════
    def _connect(self):
        name=self.dev_var.get()
        if not name or name not in self.devices:
            messagebox.showwarning("No Device","Select or add a device first."); return
        self._setbar(f"Connecting to {name}…")
        self.btn_conn.config(state=DISABLED,text="Connecting…")
        self._write(self.cmd_out,f"\nConnecting to {name}…\n","inf")
        threading.Thread(target=self._conn_worker,args=(name,),daemon=True).start()

    def _conn_worker(self, name):
        d=dict(self.devices[name])
        JK={"jump_host","jump_username","jump_password","jump_port","jump_device_type",
            "console_ap_host","console_ap_user","console_ap_pass","console_cmd","console_dev_pass"}
        cfg={k:v for k,v in d.items() if k not in JK}
        if not cfg.get("key_file"): cfg.pop("key_file",None)
        jump   = d.get("jump_host","").strip()
        con_ap = d.get("console_ap_host","").strip()
        try:
            if con_ap:
                # ── Console via AP path ────────────────────────────────────
                self.root.after(0,lambda:self._write(self.cmd_out,
                    f"  Console AP: connecting to {con_ap}…\n","wrn"))
                ap_cfg={"device_type":d.get("jump_device_type","cisco_ios"),
                        "host":con_ap,"username":d.get("console_ap_user",""),
                        "password":d.get("console_ap_pass",""),"port":22,"fast_cli":False}
                with self._lock: ap=ConnectHandler(**ap_cfg)
                # Send console command (e.g. "telnet 0" or "ssh -l admin 192.168.1.5")
                con_cmd=d.get("console_cmd","telnet 0")
                self.root.after(0,lambda:self._write(self.cmd_out,
                    f"  Console AP: sending '{con_cmd}'…\n","wrn"))
                ap.send_command_timing(con_cmd,read_timeout=15)
                # Send device password if needed
                dev_pw=d.get("console_dev_pass","")
                if dev_pw:
                    ap.send_command_timing(dev_pw+"\n",read_timeout=10)
                # Redispatch so Netmiko understands the new session type
                redispatch(ap,device_type=cfg["device_type"])
                with self._lock: self.conn=ap; self.current=name
            elif jump:
                # ── SSH Jump host path ─────────────────────────────────────
                self.root.after(0,lambda:self._write(self.cmd_out,
                    f"  Jump host: connecting to {jump}…\n","wrn"))
                jcfg={"device_type":d.get("jump_device_type","cisco_ios"),
                      "host":jump,"username":d.get("jump_username",""),
                      "password":d.get("jump_password",""),
                      "port":d.get("jump_port",22),"fast_cli":False}
                with self._lock: jc=ConnectHandler(**jcfg)
                self.root.after(0,lambda:self._write(self.cmd_out,
                    f"  Jump host: hopping to {cfg['host']}…\n","wrn"))
                jc.send_command_timing(
                    f"ssh -l {cfg['username']} -p {cfg.get('port',22)} {cfg['host']}",
                    read_timeout=15)
                jc.send_command_timing(cfg.get("password",""),read_timeout=10)
                redispatch(jc,device_type=cfg["device_type"])
                with self._lock: self.conn=jc; self.current=name
            else:
                # ── Direct SSH path ────────────────────────────────────────
                with self._lock:
                    self.conn=ConnectHandler(**cfg); self.current=name
            self.root.after(0,lambda:self._on_connected(name))
        except NetmikoAuthenticationException:
            self.root.after(0,lambda:self._conn_err("Authentication failed — check credentials."))
        except NetmikoTimeoutException:
            self.root.after(0,lambda:self._conn_err("Connection timed out — check host/port."))
        except Exception as e:
            self.root.after(0,lambda:self._conn_err(str(e)))

    def _on_connected(self, name):
        d=self.devices.get(name,{})
        jh=d.get("jump_host","").strip(); cap=d.get("console_ap_host","").strip()
        via=""
        if cap:   via=f"  (console via AP {cap})"
        elif jh:  via=f"  (jump host {jh})"
        self._write(self.cmd_out,f"✔ Connected to {name}{via}\n","ok")
        self._write(self.cmd_out,"─"*50+"\n","div")
        self._set_status(True,name)
        self.btn_conn.config(text="⚡ Connect")
        self._setbar(f"Connected — {name}{via}")
        self._t0=time.time()
        self._keepalive=True
        threading.Thread(target=self._ka_loop,daemon=True).start()
        audit_log({"device":name,"action":"connect","detail":d.get("host","")})

    def _conn_err(self, msg):
        self._write(self.cmd_out,f"\n✘ {msg}\n","err")
        self.btn_conn.config(state=NORMAL,text="⚡ Connect")
        self._setbar("Connection failed.")

    def _disconnect(self):
        self._monitoring=False; self._keepalive=False
        if hasattr(self,"ar_var"): self.ar_var.set(False)
        with self._lock:
            if self.conn:
                try: self.conn.disconnect()
                except: pass
                self.conn=None
        if self.current:
            audit_log({"device":self.current,"action":"disconnect","detail":""})
        self._write(self.cmd_out,"\nDisconnected.\n","inf")
        self._write(self.cmd_out,"─"*50+"\n","div")
        self._set_status(False); self._setbar("Disconnected.")

    def _ka_loop(self):
        while self._keepalive and self.conn:
            time.sleep(KEEPALIVE_SEC)
            if not self._keepalive or not self.conn: break
            try:
                with self._lock:
                    if self.conn:
                        self.conn.send_command_timing("show clock",read_timeout=10,
                                                       strip_prompt=True,strip_command=True)
            except: pass

    def _req(self):
        if not self.conn:
            messagebox.showerror("Not Connected","Please connect to a device first."); return False
        return True

    # ─── TEST CONNECTION ──────────────────────────────────────────────────────
    def _test_conn(self):
        name=self.dev_var.get()
        if not name or name not in self.devices:
            messagebox.showwarning("No Device","Select a device first."); return
        self._setbar(f"Testing {name}…")
        self.btn_test.config(state=DISABLED,text="Testing…")
        threading.Thread(target=self._test_worker,args=(name,),daemon=True).start()

    def _test_worker(self, name):
        d=dict(self.devices[name])
        JK={"jump_host","jump_username","jump_password","jump_port","jump_device_type",
            "console_ap_host","console_ap_user","console_ap_pass","console_cmd","console_dev_pass"}
        cfg={k:v for k,v in d.items() if k not in JK}
        if not cfg.get("key_file"): cfg.pop("key_file",None)
        try:
            c=ConnectHandler(**cfg); c.disconnect()
            self.root.after(0,lambda:(
                messagebox.showinfo("Test Passed",
                    f"✔ Connected to {d['host']} as {d['username']}\nCredentials are valid."),
                self._setbar("Test passed."),
                self.btn_test.config(state=NORMAL,text="🔍 Test")))
        except NetmikoAuthenticationException:
            self.root.after(0,lambda:(
                messagebox.showerror("Test Failed","✘ Authentication failed — wrong credentials."),
                self.btn_test.config(state=NORMAL,text="🔍 Test")))
        except Exception as e:
            self.root.after(0,lambda:(
                messagebox.showerror("Test Failed",f"✘ {e}"),
                self.btn_test.config(state=NORMAL,text="🔍 Test")))

    # ═════════════════════════════════════════════════════════════════════════
    # SEND COMMAND — unified robust method
    # ═════════════════════════════════════════════════════════════════════════
    def _send(self, cmd, timeout=60):
        """Thread-safe command sender. Returns output string."""
        with self._lock:
            if not self.conn: return "[ERROR] Not connected"
            try:
                return self.conn.send_command(cmd,expect_string=r"#",
                       read_timeout=timeout,strip_prompt=True,strip_command=True)
            except Exception:
                pass
            try:
                out=self.conn.send_command_timing(cmd,read_timeout=timeout,
                                                   strip_prompt=True,strip_command=True)
                if out and ("?" in out or "confirm" in out.lower()):
                    out+=self.conn.send_command_timing("\n",read_timeout=30,
                                                        strip_prompt=True,strip_command=True)
                return out
            except Exception as e:
                return f"[ERROR] {e}"

    def _push_cfg(self, lines):
        """Thread-safe config push. Returns output string."""
        with self._lock:
            if not self.conn: return "[ERROR] Not connected"
            try:    return self.conn.send_config_set(lines,read_timeout=30)
            except Exception as e: return f"[ERROR] {e}"

    # ─── OUTPUT HELPER ────────────────────────────────────────────────────────
    def _on_out(self, cmd, out, box):
        ts=datetime.now().strftime("%H:%M:%S")
        self._write(box,f"\n[{ts}] ▶ {cmd}\n","hdr")
        if out.startswith("[ERROR]"):
            self._write(box, out + "\n", "err")
            # ── Context-sensitive guidance based on the error message ──────
            el = out.lower()
            if "not connected" in el:
                hint = "  💡 Use Connect (F5) to open an SSH session first."
            elif "authentication" in el or "auth" in el:
                hint = "  💡 Check username / password / SSH key in Device Manager."
            elif "timeout" in el or "timed out" in el:
                hint = "  💡 Device is slow — try raising Connection Timeout in Settings → SSH."
            elif "refused" in el:
                hint = "  💡 SSH port may be wrong or the device is not accepting connections."
            elif "no route" in el or "network unreachable" in el:
                hint = "  💡 Check host/IP address and network path to the device."
            else:
                hint = "  💡 Verify the device is online and credentials are correct."
            self._write(box, hint + "\n", "wrn")
        else:
            self._write(box,out+"\n")
        self._write(box,"─"*50+"\n","div")
        if self.current:
            fn=log_save(self.current,cmd,out)
            self._write(box,f"💾 {fn}\n","inf")
            self.log.append({"timestamp":ts,"command":cmd,"output":out})
            self._mark_unsaved()

    # ─── SINGLE COMMAND ───────────────────────────────────────────────────────
    def _run_cmd(self, cmd):
        if not self._req(): return
        self._setbar(f"Running: {cmd}…")
        for b in self.cmd_btns: b.config(state=DISABLED)
        def work():
            out=self._send(cmd)
            self.root.after(0,lambda:(
                self._on_out(cmd,out,self.cmd_out),
                [b.config(state=NORMAL) for b in self.cmd_btns],
                self._setbar(f"Done: {cmd}")))
        threading.Thread(target=work,daemon=True).start()

    # ─── QUEUE RUNNER ─────────────────────────────────────────────────────────
    def _run_q(self, cmds, box, label="Batch"):
        if not self._req(): return
        self._write(box,f"\n{'─'*14} {label} ({len(cmds)} cmds) {'─'*14}\n","wrn")
        self._setbar(f"{label} running…")
        def work():
            for cmd in cmds:
                out=self._send(cmd)
                self.root.after(0,lambda c=cmd,o=out:self._on_out(c,o,box))
            self.root.after(0,lambda:(
                self._setbar(f"{label} complete."),
                self._write(box,f"\n{'─'*14} {label} COMPLETE {'─'*14}\n","ok")))
        threading.Thread(target=work,daemon=True).start()

    def _run_all_show(self):   self._run_q(ALL_SHOW,self.cmd_out,"Run All Show")
    def _health_check(self):
        self.nb.select(6); self._run_q(HEALTH_CMDS,self.mon_out,"Health Check")


    # ═════════════════════════════════════════════════════════════════════════
    # CUSTOM CLI + HISTORY
    # ═════════════════════════════════════════════════════════════════════════
    def _run_cli(self):
        if not self._req(): return
        raw=self.cli_in.get("1.0","end").strip()
        cmds=[l.strip() for l in raw.splitlines() if l.strip()]
        if not cmds: messagebox.showwarning("No Commands","Enter at least one command."); return
        for c in reversed(cmds):
            if c not in self._hist: self._hist.insert(0,c)
        self._hist=self._hist[:100]; self._hidx=-1
        self._run_q(cmds,self.cli_out,"Custom CLI")

    def _hi_up(self, ev):
        if not self._hist: return
        self._hidx=min(self._hidx+1,len(self._hist)-1)
        self.cli_in.delete("1.0","end"); self.cli_in.insert("1.0",self._hist[self._hidx])
        return "break"

    def _hi_dn(self, ev):
        self._hidx=max(self._hidx-1,-1)
        self.cli_in.delete("1.0","end")
        if self._hidx>=0: self.cli_in.insert("1.0",self._hist[self._hidx])
        return "break"

    def _hist_menu(self):
        if not self._hist: messagebox.showinfo("History","No history yet."); return
        m=tk.Menu(self.root,tearoff=0,bg=TERM_BG,fg=TERM_TEXT,font=(FONT_MONO,9))
        for cmd in self._hist[:20]:
            m.add_command(label=cmd,command=lambda c=cmd:(
                self.cli_in.delete("1.0","end"),self.cli_in.insert("1.0",c)))
        try: m.tk_popup(self.root.winfo_pointerx(),self.root.winfo_pointery())
        finally: m.grab_release()

    # ═════════════════════════════════════════════════════════════════════════
    # CONFIG WRITE HELPERS — routing field refresh
    # ═════════════════════════════════════════════════════════════════════════
    def _ref_rt(self):
        for w in self.rt_ff.winfo_children(): w.destroy()
        self.rt_flds={}
        defs={
            "Static":[("Network","network","e.g. 192.168.1.0"),
                      ("Mask","mask","e.g. 255.255.255.0"),
                      ("Next Hop","nexthop","e.g. 10.0.0.1")],
            "OSPF":  [("Process ID","pid","e.g. 1"),
                      ("Network","network","e.g. 192.168.1.0"),
                      ("Wildcard","wild","e.g. 0.0.0.255"),
                      ("Area","area","e.g. 0")],
            "EIGRP": [("AS Number","asn","e.g. 100"),
                      ("Network","network","e.g. 192.168.1.0")],
            "BGP":   [("Local AS","local_as","e.g. 65000"),
                      ("Peer IP","peer","e.g. 10.0.0.1"),
                      ("Remote AS","remote_as","e.g. 65001")],
        }
        for lbl,key,ph in defs.get(self.rt_proto.get(),[]):
            self.rt_flds[key]=self._ff(self.rt_ff,lbl,ph)

    def _ref_sec(self):
        for w in self.sec_ff.winfo_children(): w.destroy()
        self.sec_flds={}
        defs={
            "SSH":      [("Domain","domain","e.g. company.com"),
                         ("Username","user","e.g. admin"),
                         ("Password","pw","SSH user password")],
            "SNMP":     [("Community","community","e.g. public"),
                         ("Permission","permission","RO or RW"),
                         ("SNMP Host","host","e.g. 192.168.1.200")],
            "NTP":      [("NTP Server","server","e.g. 216.239.35.0")],
            "Syslog":   [("Syslog Host","host","e.g. 192.168.1.100"),
                         ("Trap Level","level","e.g. informational")],
            "ACL":      [("ACL Name","name","e.g. BLOCK_TELNET"),
                         ("Action","action","permit or deny"),
                         ("Protocol","proto","e.g. tcp"),
                         ("Source","src","e.g. 192.168.1.0 0.0.0.255"),
                         ("Destination","dst","any")],
            "Banner":   [("Message","msg","Authorized access only")],
            "Hostname": [("Hostname","name","e.g. SW-CORE-01")],
            "DNS":      [("Domain Name","domain","e.g. company.com"),
                         ("DNS Server","server1","e.g. 8.8.8.8")],
        }
        for lbl,key,ph in defs.get(self.sec_feat.get(),[]):
            self.sec_flds[key]=self._ff(self.sec_ff,lbl,ph)

    # ─── FIELD VALUE GETTERS ──────────────────────────────────────────────────
    def _gf(self, flds, phs):
        return {k:self._fv(e,phs.get(k,"")) for k,e in flds.items()}

    # ─── INTERFACE ACTIONS ────────────────────────────────────────────────────
    def _prev_iface(self):
        ph={"iface":"e.g. Gi0/1","ip":"e.g. 192.168.1.1","mask":"e.g. 255.255.255.0",
            "desc":"optional","speed":"e.g. 100 / auto","duplex":"full / half / auto"}
        v=self._gf(self.if_flds,ph); lines=[]
        if v.get("iface") and v.get("ip") and v.get("mask"):
            lines+=gen("iface_ip",{"iface":v["iface"],"ip":v["ip"],"mask":v["mask"]})
        if v.get("desc") and v.get("iface"):
            lines+=gen("iface_desc",{"iface":v["iface"],"desc":v["desc"]})
        if v.get("speed") and v.get("iface"):
            lines+=gen("iface_speed",{"iface":v["iface"],
                                       "speed":v.get("speed","auto"),
                                       "duplex":v.get("duplex","auto")})
        if not lines: self._write(self.cfg_out,"\n! Fill Interface at minimum.\n","wrn"); return
        self._cliprev(lines,self.cfg_out)

    def _apply_iface(self):
        if not self._req(): return
        ph={"iface":"e.g. Gi0/1","ip":"e.g. 192.168.1.1","mask":"e.g. 255.255.255.0",
            "desc":"optional","speed":"e.g. 100 / auto","duplex":"full / half / auto"}
        v=self._gf(self.if_flds,ph); lines=[]
        if v.get("iface") and v.get("ip") and v.get("mask"):
            lines+=gen("iface_ip",{"iface":v["iface"],"ip":v["ip"],"mask":v["mask"]})
        if v.get("desc") and v.get("iface"):
            lines+=gen("iface_desc",{"iface":v["iface"],"desc":v["desc"]})
        if v.get("speed") and v.get("iface"):
            lines+=gen("iface_speed",{"iface":v["iface"],
                                       "speed":v.get("speed","auto"),
                                       "duplex":v.get("duplex","auto")})
        if not lines: messagebox.showwarning("Incomplete","Fill Interface at minimum."); return
        self._do_push(lines,"interface_config",str(v))

    def _shut(self):
        if not self._req(): return
        i=self._fv(self.if_flds["iface"],"e.g. Gi0/1")
        if not i: messagebox.showwarning("Missing","Enter an interface."); return
        self._do_push(gen("iface_shutdown",{"iface":i}),"shutdown",i)

    def _noshut(self):
        if not self._req(): return
        i=self._fv(self.if_flds["iface"],"e.g. Gi0/1")
        if not i: messagebox.showwarning("Missing","Enter an interface."); return
        self._do_push(gen("iface_noshut",{"iface":i}),"no_shutdown",i)

    def _write_mem(self):
        if not self._req(): return
        self._setbar("Saving config (write memory)…")
        def work():
            out=self._send("write memory",timeout=30)
            self.root.after(0,lambda:(
                self._write(self.cfg_out,f"\n✔ write memory:\n{out}\n","ok"),
                self._setbar("Config saved to NVRAM.")))
            audit_log({"device":self.current,"action":"write_memory","detail":""})
        threading.Thread(target=work,daemon=True).start()

    # ─── VLAN ACTIONS ─────────────────────────────────────────────────────────
    def _prev_vlan(self):
        ph={"vlan_id":"e.g. 10","name":"e.g. SALES","iface":"e.g. Fa0/1"}
        v=self._gf(self.vl_flds,ph); lines=[]
        if v.get("vlan_id") and v.get("name"):
            lines+=gen("vlan_create",{"vlan_id":v["vlan_id"],"name":v["name"]})
        if v.get("iface") and v.get("vlan_id"):
            t="vlan_access" if self.vlan_mode.get()=="access" else "vlan_trunk"
            lines+=gen(t,{"iface":v["iface"],"vlan_id":v["vlan_id"]})
        self._cliprev(lines or ["! Fill VLAN fields."],self.cfg_out)

    def _apply_vlan(self):
        if not self._req(): return
        ph={"vlan_id":"e.g. 10","name":"e.g. SALES","iface":"e.g. Fa0/1"}
        v=self._gf(self.vl_flds,ph); lines=[]
        if v.get("vlan_id") and v.get("name"):
            lines+=gen("vlan_create",{"vlan_id":v["vlan_id"],"name":v["name"]})
        if v.get("iface") and v.get("vlan_id"):
            t="vlan_access" if self.vlan_mode.get()=="access" else "vlan_trunk"
            lines+=gen(t,{"iface":v["iface"],"vlan_id":v["vlan_id"]})
        if not lines: messagebox.showwarning("Incomplete","Fill VLAN ID and Name."); return
        self._do_push(lines,"vlan_config",str(v))

    # ─── ROUTING ACTIONS ──────────────────────────────────────────────────────
    def _prev_rt(self):
        ph={"network":"e.g. 192.168.1.0","mask":"e.g. 255.255.255.0","nexthop":"e.g. 10.0.0.1",
            "pid":"e.g. 1","wild":"e.g. 0.0.0.255","area":"e.g. 0",
            "asn":"e.g. 100","local_as":"e.g. 65000","peer":"e.g. 10.0.0.1","remote_as":"e.g. 65001"}
        tmap={"Static":"static_route","OSPF":"ospf","EIGRP":"eigrp","BGP":"bgp"}
        lines=gen(tmap[self.rt_proto.get()],self._gf(self.rt_flds,ph))
        self._cliprev(lines,self.cfg_out)

    def _apply_rt(self):
        if not self._req(): return
        ph={"network":"e.g. 192.168.1.0","mask":"e.g. 255.255.255.0","nexthop":"e.g. 10.0.0.1",
            "pid":"e.g. 1","wild":"e.g. 0.0.0.255","area":"e.g. 0",
            "asn":"e.g. 100","local_as":"e.g. 65000","peer":"e.g. 10.0.0.1","remote_as":"e.g. 65001"}
        tmap={"Static":"static_route","OSPF":"ospf","EIGRP":"eigrp","BGP":"bgp"}
        lines=gen(tmap[self.rt_proto.get()],self._gf(self.rt_flds,ph))
        if any(l.startswith("! ERROR") for l in lines):
            messagebox.showwarning("Incomplete","Fill in all fields."); return
        self._do_push(lines,"routing_config",self.rt_proto.get())

    # ─── SECURITY / SERVICES ACTIONS ──────────────────────────────────────────
    def _prev_sec(self):
        v=self._gsecv()
        lines=gen(self._seccli(),v)
        self._cliprev(lines,self.cfg_out)

    def _apply_sec(self):
        if not self._req(): return
        v=self._gsecv(); lines=gen(self._seccli(),v)
        if any(l.startswith("! ERROR") for l in lines):
            messagebox.showwarning("Incomplete","Fill in all fields."); return
        self._do_push(lines,"security_config",self.sec_feat.get())

    def _gsecv(self):
        ph={"domain":"e.g. company.com","user":"e.g. admin","pw":"password",
            "community":"e.g. public","permission":"RO or RW","host":"e.g. 192.168.1.100",
            "server":"e.g. 216.239.35.0","level":"informational",
            "name":"e.g. BLOCK_TELNET","action":"permit or deny","proto":"e.g. tcp",
            "src":"e.g. 192.168.1.0 0.0.0.255","dst":"any","msg":"Authorized access only",
            "server1":"e.g. 8.8.8.8"}
        return {k:self._fv(e,ph.get(k,"")) for k,e in self.sec_flds.items()}

    def _seccli(self):
        f=self.sec_feat.get()
        if f=="SSH":     return "ssh_setup"
        if f=="SNMP":
            v=self._gsecv()
            return "snmp_rw" if v.get("permission","").upper()=="RW" else "snmp_ro"
        if f=="NTP":     return "ntp_full"
        if f=="Syslog":  return "syslog"
        if f=="ACL":
            v=self._gsecv()
            return "acl_permit" if v.get("action","").lower().startswith("p") else "acl_deny"
        if f=="Banner":  return "banner"
        if f=="Hostname":return "hostname"
        if f=="DNS":     return "dns"
        return ""

    # ─── PORT SECURITY ────────────────────────────────────────────────────────
    def _prev_ps(self):
        ph={"iface":"e.g. Fa0/1","max":"e.g. 2","action":"shutdown / restrict / protect"}
        v=self._gf(self.ps_flds,ph)
        lines=gen("port_security",v)
        self._cliprev(lines,self.cfg_out)

    def _apply_ps(self):
        if not self._req(): return
        ph={"iface":"e.g. Fa0/1","max":"e.g. 2","action":"shutdown / restrict / protect"}
        v=self._gf(self.ps_flds,ph)
        lines=gen("port_security",v)
        if any(l.startswith("! ERROR") for l in lines):
            messagebox.showwarning("Incomplete","Fill in all fields."); return
        self._do_push(lines,"port_security",str(v))

    # ─── CONFIG PUSH CORE ────────────────────────────────────────────────────
    def _cliprev(self, lines, box):
        self._write(box,"\n─── CLI PREVIEW ──────────────────────\n","div")
        for l in lines: self._write(box,l+"\n","inf")
        self._write(box,"──────────────────────────────────────\n","div")

    def _do_push(self, lines, action, detail=""):
        self._write(self.cfg_out,"\n▶ Pushing config…\n","inf")
        self._cliprev(lines,self.cfg_out)
        def work():
            out=self._push_cfg(lines)
            self.root.after(0,lambda:(
                self._write(self.cfg_out,"\n✔ Applied:\n","ok"),
                self._write(self.cfg_out,out+"\n"),
                self._write(self.cfg_out,"─"*50+"\n","div"),
                self._setbar("Config applied."),
                self._mark_unsaved()))
            audit_log({"device":self.current or "?","action":action,"detail":detail})
        threading.Thread(target=work,daemon=True).start()


    # ═════════════════════════════════════════════════════════════════════════
    # TROUBLESHOOT ACTIONS
    # ═════════════════════════════════════════════════════════════════════════
    def _run_ts(self, cmd):
        if not self._req(): return
        threading.Thread(target=lambda:(
            self.root.after(0,lambda:self._on_out(cmd,self._send(cmd),self.ts_out))
        ),daemon=True).start()

    def _ping(self):
        if not self._req(): return
        ip=self.trbl_ip.get().strip()
        if not ip: messagebox.showwarning("Missing","Enter a target IP."); return
        try: cnt=int(self.trbl_cnt.get())
        except: cnt=5
        cmd=f"ping {ip} repeat {cnt}"
        self._setbar(f"Pinging {ip}…")
        def work():
            with self._lock:
                try:
                    out=self.conn.send_command_timing(cmd,read_timeout=60,
                                                       strip_prompt=True,strip_command=True)
                    if "?" in out or "confirm" in out.lower():
                        out+=self.conn.send_command_timing("\n",read_timeout=30,
                                                            strip_prompt=True,strip_command=True)
                except Exception as e: out=f"[ERROR] {e}"
            self.root.after(0,lambda:self._on_out(cmd,out,self.ts_out))
        threading.Thread(target=work,daemon=True).start()

    def _trace(self):
        if not self._req(): return
        ip=self.trbl_ip.get().strip()
        if not ip: messagebox.showwarning("Missing","Enter a target IP."); return
        cmd=f"traceroute {ip}"
        self._setbar(f"Traceroute to {ip}…")
        def work():
            with self._lock:
                try: out=self.conn.send_command_timing(cmd,read_timeout=120,
                                                        strip_prompt=True,strip_command=True)
                except Exception as e: out=f"[ERROR] {e}"
            self.root.after(0,lambda:self._on_out(cmd,out,self.ts_out))
        threading.Thread(target=work,daemon=True).start()

    def _tcp_test(self):
        if not self._req(): return
        ip=self.trbl_ip.get().strip(); port=self.tcp_port.get().strip()
        if not ip: messagebox.showwarning("Missing","Enter a target IP."); return
        if not port: port="22"
        cmd=f"telnet {ip} {port}"
        self._write(self.ts_out,f"\n[TCP Test] Attempting {ip}:{port}…\n","wrn")
        def work():
            with self._lock:
                try:
                    out=self.conn.send_command_timing(cmd,read_timeout=15,
                                                       strip_prompt=True,strip_command=True)
                    # Exit telnet if it connected
                    if "connected" in out.lower() or "escape" in out.lower():
                        self.conn.send_command_timing("\x1d",read_timeout=5)
                        self.conn.send_command_timing("q\n",read_timeout=5)
                except Exception as e: out=f"[ERROR] {e}"
            self.root.after(0,lambda:self._on_out(cmd,out,self.ts_out))
        threading.Thread(target=work,daemon=True).start()

    def _show_errors(self):
        if not self._req(): return
        iface=self.trbl_iface.get().strip()
        cmd=f"show interfaces {iface}" if iface else "show interfaces counters errors"
        threading.Thread(target=lambda:self.root.after(0,
            lambda:self._on_out(cmd,self._send(cmd),self.ts_out)),daemon=True).start()

    def _clear_cnt(self):
        if not self._req(): return
        iface=self.trbl_iface.get().strip()
        if not iface: messagebox.showwarning("Missing","Enter an interface."); return
        if not messagebox.askyesno("Confirm",f"Clear counters on {iface}?"): return
        lines=gen("clear_iface",{"iface":iface})
        def work():
            out=self._push_cfg(lines)
            self.root.after(0,lambda:(
                self._write(self.ts_out,f"\n✔ Cleared counters on {iface}\n","ok"),
                self._write(self.ts_out,out+"\n")))
            audit_log({"device":self.current,"action":"clear_counters","detail":iface})
        threading.Thread(target=work,daemon=True).start()

    def _clear_arp(self):
        if not self._req(): return
        if not messagebox.askyesno("Confirm","Clear ARP cache on device?"): return
        def work():
            out=self._push_cfg(gen("clear_arp",{}))
            self.root.after(0,lambda:(
                self._write(self.ts_out,"\n✔ ARP cache cleared\n","ok"),
                self._write(self.ts_out,out+"\n")))
            audit_log({"device":self.current,"action":"clear_arp","detail":""})
        threading.Thread(target=work,daemon=True).start()

    def _clear_mac(self):
        if not self._req(): return
        if not messagebox.askyesno("Confirm","Clear MAC address table?"): return
        def work():
            out=self._push_cfg(gen("clear_mac",{}))
            self.root.after(0,lambda:(
                self._write(self.ts_out,"\n✔ MAC address table cleared\n","ok"),
                self._write(self.ts_out,out+"\n")))
            audit_log({"device":self.current,"action":"clear_mac_table","detail":""})
        threading.Thread(target=work,daemon=True).start()

    # ═════════════════════════════════════════════════════════════════════════
    # MONITORING
    # ═════════════════════════════════════════════════════════════════════════
    def _run_mon(self, cmd):
        if not self._req(): return
        threading.Thread(target=lambda:self.root.after(0,
            lambda:self._on_out(cmd,self._send(cmd),self.mon_out)),daemon=True).start()

    def _toggle_ar(self):
        if self.ar_var.get():
            if not self._req(): self.ar_var.set(False); return
            self._monitoring=True; self._ar_loop()
        else: self._monitoring=False

    def _ar_loop(self):
        if not self._monitoring or not self.conn: return
        cmd=self.ar_cmd.get().strip() or "show ip interface brief"
        try: iv=int(self.ar_int.get())
        except: iv=30
        threading.Thread(target=lambda:self.root.after(0,
            lambda:self._on_out(cmd,self._send(cmd),self.mon_out)),daemon=True).start()
        if self._monitoring: self.root.after(iv*1000,self._ar_loop)

    # ═════════════════════════════════════════════════════════════════════════
    # BACKUP & RESTORE
    # ═════════════════════════════════════════════════════════════════════════
    def _bak_pull(self):
        if not self._req(): return
        btype=self.bak_type.get()
        self._setbar(f"Pulling {btype} config…")
        def work():
            out=self._send(f"show {btype}-config",timeout=90)
            if out.startswith("[ERROR]"):
                self.root.after(0,lambda:self._write(self.bak_out,f"\n{out}\n","err")); return
            fn=backup_save(self.current,out,btype)
            audit_log({"device":self.current,"action":"backup","detail":fn})
            self.root.after(0,lambda:(
                self._clr(self.bak_out),
                self._write(self.bak_out,f"✔ Saved: {fn}\n\n","ok"),
                self._write(self.bak_out,out),
                self._ref_baklist(),
                self._setbar(f"Backup saved: {os.path.basename(fn)}")))
        threading.Thread(target=work,daemon=True).start()

    def _quick_bak(self):
        if not self._req(): return
        self._setbar("Quick backup (running-config)…")
        def work():
            out=self._send("show running-config",timeout=90)
            if out.startswith("[ERROR]"): return
            fn=backup_save(self.current,out,"running")
            audit_log({"device":self.current,"action":"quick_backup","detail":fn})
            self.root.after(0,lambda:(
                self._ref_baklist(),
                self._setbar(f"Quick backup saved: {os.path.basename(fn)}")))
        threading.Thread(target=work,daemon=True).start()

    def _ref_baklist(self):
        self.bak_lb.delete(0,"end")
        if not os.path.isdir(BACKUP_DIR): return
        for fn in sorted([f for f in os.listdir(BACKUP_DIR) if f.endswith(".txt")],reverse=True):
            self.bak_lb.insert("end",fn)

    def _bak_preview(self, _=None):
        sel=self.bak_lb.curselection()
        if not sel: return
        fn=os.path.join(BACKUP_DIR,self.bak_lb.get(sel[0]))
        try:
            with open(fn,encoding="utf-8") as f: content=f.read()
            self._clr(self.bak_out); self._write(self.bak_out,content)
        except Exception as e:
            self._write(self.bak_out,f"\n[ERROR] {e}\n","err")

    def _open_bakfolder(self):
        os.makedirs(BACKUP_DIR,exist_ok=True); path=os.path.abspath(BACKUP_DIR)
        try: os.startfile(path)
        except: subprocess.Popen(["xdg-open",path])

    def _restore_cfg(self):
        if not self._req(): return
        fn=filedialog.askopenfilename(
            title="Select Config to Restore",
            initialdir=BACKUP_DIR if os.path.isdir(BACKUP_DIR) else ".",
            filetypes=[("Text","*.txt"),("All","*.*")])
        if not fn: return
        if not messagebox.askyesno("Confirm Restore",
            f"Push this config to {self.current}?\n\n{os.path.basename(fn)}\n\n"
            "This will overwrite the running configuration."): return
        def work():
            try:
                with open(fn,encoding="utf-8") as f: lines=f.read().splitlines()
                lines=[l for l in lines if l.strip() and not l.startswith("!")
                       and not l.startswith("Building") and not l.startswith("Current")]
                out=self._push_cfg(lines)
                self.root.after(0,lambda:(
                    self._write(self.bak_out,f"\n✔ Config restored from {os.path.basename(fn)}\n","ok"),
                    self._write(self.bak_out,out[:2000]+"\n"),
                    self._setbar("Config restored.")))
                audit_log({"device":self.current,"action":"restore_config","detail":fn})
            except Exception as e:
                self.root.after(0,lambda:self._write(self.bak_out,f"\n✘ Restore error: {e}\n","err"))
        threading.Thread(target=work,daemon=True).start()

    def _batch_bak_all(self):
        if not messagebox.askyesno("Batch Backup",
            "Backup running-config on ALL devices?\nEach device opens its own SSH connection."): return
        self._write(self.bak_out,"\n▶▶ Batch backup all devices…\n","wrn")
        threading.Thread(target=self._batch_bak_worker,daemon=True).start()

    def _batch_bak_worker(self):
        JK={"jump_host","jump_username","jump_password","jump_port","jump_device_type",
            "console_ap_host","console_ap_user","console_ap_pass","console_cmd","console_dev_pass"}
        _total = len(self.devices); _done = 0
        self.root.after(0, lambda: self._setbar(f"Batch backup: 0 / {_total} devices…"))
        for name,d in self.devices.items():
            cfg={k:v for k,v in d.items() if k not in JK}
            if not cfg.get("key_file"): cfg.pop("key_file",None)
            try:
                c=ConnectHandler(**cfg)
                out=c.send_command("show running-config",expect_string=r"#",
                                   read_timeout=90,strip_prompt=True,strip_command=True)
                c.disconnect()
                fn=backup_save(name,out,"running")
                audit_log({"device":name,"action":"batch_backup","detail":fn})
                _done += 1
                self.root.after(0, lambda n=name, f=fn, d=_done, t=_total: (
                    self._write(self.bak_out, f"✔ [{d}/{t}] {n} → {os.path.basename(f)}\n", "ok"),
                    self._setbar(f"Batch backup: {d} / {t} devices…")))
            except Exception as e:
                _done += 1
                self.root.after(0, lambda n=name, err=str(e), d=_done, t=_total: (
                    self._write(self.bak_out, f"✘ [{d}/{t}] {n}: {err}\n", "err"),
                    self._setbar(f"Batch backup: {d} / {t} devices…")))
        self.root.after(0,lambda:(self._ref_baklist(),self._setbar("Batch backup complete.")))

    # ═════════════════════════════════════════════════════════════════════════
    # SCHEDULED BACKUPS
    # ═════════════════════════════════════════════════════════════════════════
    def _sched_dlg(self):
        win=tk.Toplevel(self.root); win.title("Schedule Backups")
        win.geometry("480x340"); win.grab_set(); win.configure(bg=TERM_BG)
        ttk.Label(win,text="Scheduled Backup",font=(FONT_MONO,11,"bold"),
                  bootstyle="primary").pack(pady=(14,4))
        ttk.Label(win,text="Run a backup automatically at a set interval.",
                  font=(FONT_MONO,8),bootstyle="secondary").pack()
        cf=ttk.Frame(win,padding=(20,10)); cf.pack(fill=X)
        ttk.Label(cf,text="Interval (hours):",font=(FONT_MONO,9,"bold")).grid(row=0,column=0,sticky=W,pady=4)
        iv=ttk.Spinbox(cf,from_=1,to=168,width=6,font=(FONT_MONO,10)); iv.set(24)
        iv.grid(row=0,column=1,sticky=W,padx=8)
        ttk.Label(cf,text="Config Type:",font=(FONT_MONO,9,"bold")).grid(row=1,column=0,sticky=W,pady=4)
        ct=tk.StringVar(value="running")
        for i,m in enumerate(["running","startup"]):
            ttk.Radiobutton(cf,text=m.capitalize(),variable=ct,value=m,
                            bootstyle="primary").grid(row=1,column=i+1,sticky=W,padx=4)

        self.sched_status=ttk.Label(win,text="Status: Not scheduled",
                                     font=(FONT_MONO,8),bootstyle="secondary")
        self.sched_status.pack(pady=8)

        bf=ttk.Frame(win); bf.pack(pady=8)
        def start():
            try: hrs=float(iv.get())
            except: messagebox.showwarning("Invalid","Enter a valid number of hours.",parent=win); return
            self._start_sched(hrs,ct.get())
            self.sched_status.config(text=f"Status: Scheduled every {hrs}h ({ct.get()}-config)")
        def stop():
            self._sched_running=False
            self.sched_status.config(text="Status: Stopped")
        ttk.Button(bf,text="▶ Start",command=start,bootstyle="success",width=12).pack(side=LEFT,padx=6)
        ttk.Button(bf,text="■ Stop", command=stop, bootstyle="danger-outline",width=12).pack(side=LEFT,padx=6)
        ttk.Button(bf,text="Close", command=win.destroy,bootstyle="secondary-outline",width=12).pack(side=LEFT,padx=6)

    def _start_sched(self, hours, btype):
        self._sched_running=True
        def loop():
            while getattr(self,"_sched_running",False):
                time.sleep(hours*3600)
                if not getattr(self,"_sched_running",False): break
                if self.conn and self.current:
                    out=self._send(f"show {btype}-config",timeout=90)
                    if not out.startswith("[ERROR]"):
                        fn=backup_save(self.current,out,btype)
                        audit_log({"device":self.current,"action":"scheduled_backup","detail":fn})
                        self.root.after(0,lambda f=fn:self._setbar(
                            f"Scheduled backup saved: {os.path.basename(f)}"))
        threading.Thread(target=loop,daemon=True).start()

    # ═════════════════════════════════════════════════════════════════════════
    # CONFIG DIFF
    # ═════════════════════════════════════════════════════════════════════════
    def _diff_loadfile(self, slot):
        fn=filedialog.askopenfilename(title=f"Load Config {slot}",
                                      filetypes=[("Text","*.txt"),("All","*.*")])
        if not fn: return
        with open(fn,encoding="utf-8",errors="replace") as f: content=f.read()
        if slot=="A":
            self._diff_a=content
            self.diff_a_lbl.config(text=f"A: {os.path.basename(fn)}")
        else:
            self._diff_b=content
            self.diff_b_lbl.config(text=f"B: {os.path.basename(fn)}")
        self._setbar(f"Config {slot} loaded")

    def _diff_pull(self, slot, btype):
        if not self._req(): return
        self._setbar(f"Pulling {btype} config → {slot}…")
        def work():
            out=self._send(f"show {btype}-config",timeout=90)
            if slot=="A":
                self._diff_a=out
                self.root.after(0,lambda:self.diff_a_lbl.config(
                    text=f"A: {self.current} {btype}-config (live)"))
            else:
                self._diff_b=out
                self.root.after(0,lambda:self.diff_b_lbl.config(
                    text=f"B: {self.current} {btype}-config (live)"))
            self.root.after(0,lambda:self._setbar(f"Config {slot} pulled"))
        threading.Thread(target=work,daemon=True).start()

    def _run_diff(self):
        if not self._diff_a or not self._diff_b:
            messagebox.showwarning("Missing","Load or pull both Config A and B first."); return
        a=self._diff_a.splitlines(); b=self._diff_b.splitlines()
        diff=list(difflib.unified_diff(a,b,lineterm="",fromfile="Config A",tofile="Config B"))
        self._clr(self.diff_out)
        if not diff:
            self._write(self.diff_out,"✔ Configs are identical — no differences.\n","ok"); return
        self._write(self.diff_out,f"Diff: {len(diff)} differing line(s)\n\n","wrn")
        for line in diff:
            if line.startswith("+"): self._write(self.diff_out,line+"\n","add")
            elif line.startswith("-"): self._write(self.diff_out,line+"\n","rem")
            else: self._write(self.diff_out,line+"\n","div")

    # ═════════════════════════════════════════════════════════════════════════
    # MULTI-DEVICE
    # ═════════════════════════════════════════════════════════════════════════
    def _ref_multi(self):
        if hasattr(self,"multi_lb"):
            self.multi_lb.delete(0,"end")
            for n in self.devices: self.multi_lb.insert("end",n)

    def _run_multi(self):
        sel=self.multi_lb.curselection()
        if not sel: messagebox.showwarning("No Selection","Select at least one device."); return
        names=[self.multi_lb.get(i) for i in sel]
        op=self.multi_op.get()
        raw=self.multi_cmd.get("1.0","end").strip()
        if not raw and op in ("Run Command","Push Config"):
            messagebox.showwarning("No Command","Enter a command or config lines."); return
        total = len(names)
        self._write(self.multi_out,
                    f"\n{'─'*14} {op} on {total} device(s) {'─'*14}\n","wrn")
        self._setbar(f"{op}: 0 / {total} devices…")
        threading.Thread(target=self._multi_worker,args=(names,op,raw),daemon=True).start()

    def _multi_worker(self, names, op, raw):
        JK={"jump_host","jump_username","jump_password","jump_port","jump_device_type",
            "console_ap_host","console_ap_user","console_ap_pass","console_cmd","console_dev_pass"}
        _total = len(names); _done = 0
        for name in names:
            _done += 1
            self.root.after(0, lambda n=name, d=_done, t=_total: (
                self._write(self.multi_out, f"\n▶ [{d}/{t}] {n}\n", "hdr"),
                self._setbar(f"{op}: {d} / {t} — {n}")))
            d=dict(self.devices[name])
            cfg={k:v for k,v in d.items() if k not in JK}
            if not cfg.get("key_file"): cfg.pop("key_file",None)
            try:
                c=ConnectHandler(**cfg)
                if op=="Run Command":
                    out=c.send_command(raw,expect_string=r"#",read_timeout=60,
                                       strip_prompt=True,strip_command=True)
                elif op=="Push Config":
                    lines=[l.strip() for l in raw.splitlines() if l.strip()]
                    out=c.send_config_set(lines,read_timeout=30)
                elif op=="Collect Inventory":
                    out="\n".join(c.send_command(cmd,expect_string=r"#",read_timeout=60,
                                                  strip_prompt=True,strip_command=True)
                                  for cmd in ["show version","show ip interface brief","show vlan brief"])
                elif op=="Backup All":
                    out=c.send_command("show running-config",expect_string=r"#",
                                       read_timeout=90,strip_prompt=True,strip_command=True)
                    fn=backup_save(name,out,"running")
                    out=f"Saved: {fn}"
                else:
                    out="Unknown operation"
                c.disconnect()
                self.root.after(0,lambda n=name,o=out:(
                    self._write(self.multi_out,o+"\n"),
                    self._write(self.multi_out,"─"*50+"\n","div")))
                audit_log({"device":name,"action":f"multi_{op}","detail":raw[:100]})
            except Exception as e:
                self.root.after(0,lambda n=name,err=str(e):
                    self._write(self.multi_out,f"✘ {n}: {err}\n","err"))
        self.root.after(0,lambda:self._write(self.multi_out,"\n✔ Batch complete.\n","ok"))

    # ═════════════════════════════════════════════════════════════════════════
    # INVENTORY
    # ═════════════════════════════════════════════════════════════════════════
    def _collect_inv(self):
        if not self._req(): return
        self._setbar("Collecting inventory…")
        self.nb.select(8)
        threading.Thread(target=self._inv_worker,args=(self.current,self.conn,False),daemon=True).start()

    def _collect_all_inv(self):
        self._write(self.inv_out,"\n▶▶ Collecting inventory from all devices…\n","wrn")
        threading.Thread(target=self._all_inv_worker,daemon=True).start()

    def _inv_worker(self, dev, conn_obj, is_batch):
        results={"device":dev,"timestamp":datetime.now().isoformat()}
        JK={"jump_host","jump_username","jump_password","jump_port","jump_device_type",
            "console_ap_host","console_ap_user","console_ap_pass","console_cmd","console_dev_pass"}
        for cmd in INVENTORY_CMDS:
            try:
                with self._lock if not is_batch else threading.Lock():
                    out=conn_obj.send_command(cmd,expect_string=r"#",read_timeout=60,
                                              strip_prompt=True,strip_command=True)
                results[cmd]=out
            except Exception as e:
                results[cmd]=f"[ERROR] {e}"
        self._inv_data[dev]=results
        self.root.after(0,lambda:self._render_inv(dev,results))

    def _all_inv_worker(self):
        JK={"jump_host","jump_username","jump_password","jump_port","jump_device_type",
            "console_ap_host","console_ap_user","console_ap_pass","console_cmd","console_dev_pass"}
        for name,d in self.devices.items():
            cfg={k:v for k,v in d.items() if k not in JK}
            if not cfg.get("key_file"): cfg.pop("key_file",None)
            self.root.after(0,lambda n=name:self._write(self.inv_out,f"\n▶ Connecting to {n}…\n","wrn"))
            try:
                c=ConnectHandler(**cfg)
                results={"device":name,"timestamp":datetime.now().isoformat()}
                for cmd in INVENTORY_CMDS:
                    try:
                        out=c.send_command(cmd,expect_string=r"#",read_timeout=60,
                                           strip_prompt=True,strip_command=True)
                        results[cmd]=out
                    except Exception as e: results[cmd]=f"[ERROR] {e}"
                c.disconnect()
                self._inv_data[name]=results
                self.root.after(0,lambda n=name,r=results:self._render_inv(n,r))
            except Exception as e:
                self.root.after(0,lambda n=name,err=str(e):
                    self._write(self.inv_out,f"✘ {n}: {err}\n","err"))
        self.root.after(0,lambda:self._write(self.inv_out,"\n✔ Inventory collection complete.\n","ok"))

    def _render_inv(self, dev, data):
        self._write(self.inv_out,f"\n{'═'*50}\n","div")
        self._write(self.inv_out,f"DEVICE: {dev}  [{data.get('timestamp','')}]\n","hdr")
        self._write(self.inv_out,f"{'═'*50}\n","div")
        for cmd in INVENTORY_CMDS:
            out=data.get(cmd,"")
            if out and not out.startswith("[ERROR]"):
                self._write(self.inv_out,f"\n▶ {cmd}\n","cyn")
                self._write(self.inv_out,out[:1500]+"\n")
                self._write(self.inv_out,"─"*40+"\n","div")

    def _exp_inv_csv(self):
        if not self._inv_data:
            messagebox.showinfo("No Data","Run inventory collection first."); return
        fn=filedialog.asksaveasfilename(defaultextension=".csv",
                                        initialfile="network_inventory.csv",
                                        filetypes=[("CSV","*.csv")])
        if not fn: return
        with open(fn,"w",newline="",encoding="utf-8") as f:
            w=csv.writer(f)
            w.writerow(["Device","Timestamp","Command","Output"])
            for dev,data in self._inv_data.items():
                ts=data.get("timestamp","")
                for cmd in INVENTORY_CMDS:
                    out=data.get(cmd,"")
                    w.writerow([dev,ts,cmd,out[:2000]])
        messagebox.showinfo("Exported",f"Inventory saved:\n{fn}")

    # ═════════════════════════════════════════════════════════════════════════
    # AUDIT LOG
    # ═════════════════════════════════════════════════════════════════════════
    def _load_audit(self):
        self._clr(self.audit_out)
        recs=[]
        if os.path.exists(AUDIT_FILE):
            try:
                with open(AUDIT_FILE,encoding="utf-8") as f: recs=json.load(f)
            except: pass
        if not recs:
            self._write(self.audit_out,"No audit records yet.\n","inf"); return
        for r in reversed(recs[-500:]):
            ts=r.get("ts","?"); dev=r.get("device","?")
            act=r.get("action","?"); det=r.get("detail","")
            self._write(self.audit_out,f"[{ts}] ","div")
            self._write(self.audit_out,f"{dev}","hdr")
            self._write(self.audit_out,f"  {act}","inf")
            if det: self._write(self.audit_out,f"  →  {str(det)[:80]}","wrn")
            self._write(self.audit_out,"\n")

    def _clr_audit(self):
        if messagebox.askyesno("Clear","Delete all audit records?"):
            if os.path.exists(AUDIT_FILE): os.remove(AUDIT_FILE)
            self._load_audit(); self._setbar("Audit log cleared.")

    def _exp_audit(self):
        if not os.path.exists(AUDIT_FILE):
            messagebox.showinfo("No Log","No audit log found."); return
        dest=filedialog.asksaveasfilename(defaultextension=".json",
                                          initialfile="audit_export.json",
                                          filetypes=[("JSON","*.json")])
        if dest: shutil.copy(AUDIT_FILE,dest); messagebox.showinfo("Exported",dest)

    # ═════════════════════════════════════════════════════════════════════════
    # EMAIL
    # ═════════════════════════════════════════════════════════════════════════
    def _save_em(self):
        data={k:e.get().strip() for k,e in self.em_flds.items()}
        data["subject"]=self.em_subj.get().strip()
        enc_save(EMAIL_CFG_FILE,data)
        messagebox.showinfo("Saved","Email settings saved (encrypted).")
        self._setbar("Email settings saved.")

    def _gen_report(self):
        self._clr(self.em_out)
        ts=datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        self._write(self.em_out,"SHIKANET REPORT\n","hdr")
        self._write(self.em_out,f"Generated : {ts}\n","inf")
        self._write(self.em_out,f"Device    : {self.current or 'N/A'}\n","inf")
        self._write(self.em_out,f"Commands  : {len(self.log)}\n","inf")
        if self._notes:
            self._write(self.em_out,f"Notes     : {self._notes[:300]}\n","wrn")
        self._write(self.em_out,"\n"+"─"*50+"\n","div")
        for e in self.log:
            self._write(self.em_out,f"[{e['timestamp']}] {e['command']}\n","hdr")
            self._write(self.em_out,e["output"][:500]+"\n")
            self._write(self.em_out,"─"*50+"\n","div")

    def _send_em(self):
        f={k:e.get().strip() for k,e in self.em_flds.items()}
        f["subject"]=self.em_subj.get().strip() or "ShikaNet Report"
        for k,lbl in [("smtp","SMTP Server"),("port","SMTP Port"),
                       ("user","From Email"),("to","To Email")]:
            if not f.get(k):
                messagebox.showwarning("Missing",f"Fill in '{lbl}'."); return
        threading.Thread(target=self._em_worker,args=(f,),daemon=True).start()

    def _em_worker(self, f):
        try:
            msg=MIMEMultipart()
            msg["From"]=f["user"]; msg["To"]=f["to"]; msg["Subject"]=f["subject"]
            body=(f"ShikaNet Report\nDevice: {self.current}\n"
                  f"Date: {datetime.now()}\nCommands: {len(self.log)}\n"
                  f"Notes: {self._notes[:500]}\n")
            msg.attach(MIMEText(body,"plain"))
            atts=[]
            if self.att_log.get() and self.current:
                fn=f"{sn(self.current)}_{STS}.txt"
                if os.path.exists(fn): atts.append(fn)
            if self.att_json.get() and self.log:
                atts.append(to_json(self.current or "report",self.log))
            for fp in atts:
                with open(fp,"rb") as fl:
                    p=MIMEBase("application","octet-stream"); p.set_payload(fl.read())
                encoders.encode_base64(p)
                p.add_header("Content-Disposition",f"attachment; filename={os.path.basename(fp)}")
                msg.attach(p)
            srv=smtplib.SMTP(f["smtp"],int(f["port"])); srv.starttls()
            if f.get("pass"): srv.login(f["user"],f["pass"])
            srv.sendmail(f["user"],f["to"],msg.as_string()); srv.quit()
            self.root.after(0,lambda:(
                self._write(self.em_out,"\n✔ Email sent!\n","ok"),
                self._setbar("Email sent."),self._mark_saved()))
        except Exception as e:
            self.root.after(0,lambda:self._write(self.em_out,f"\n✘ Email error: {e}\n","err"))

    # ═════════════════════════════════════════════════════════════════════════
    # DEVICE MANAGER
    # ═════════════════════════════════════════════════════════════════════════
    def _dev_refresh(self):
        self.dev_lb.delete(0,"end")
        for n in self.devices: self.dev_lb.insert("end",n)
        self.dev_cb.configure(values=list(self.devices.keys()))
        if self.devices and self.dev_var.get() not in self.devices:
            self.dev_var.set(list(self.devices.keys())[0])
        self._ref_multi()

    def _dev_sel(self, _=None):
        sel=self.dev_lb.curselection()
        if not sel: return
        name=self.dev_lb.get(sel[0]); d=self.devices.get(name,{})
        self._clr(self.dev_det)
        for txt,tag in [
            (f"Name        : {name}\n","hdr"),
            (f"Host        : {d.get('host','')}\n","inf"),
            (f"Username    : {d.get('username','')}\n","inf"),
            (f"Password    : {'*'*len(d.get('password',''))}\n","inf"),
            (f"Port        : {d.get('port',22)}\n","inf"),
            (f"Device Type : {d.get('device_type','')}\n","inf"),
            (f"fast_cli    : {d.get('fast_cli',False)}\n","inf"),
            (f"Key File    : {d.get('key_file','') or '(password auth)'}\n","inf"),
            ("─"*40+"\n","div"),
        ]:
            self._write(self.dev_det,txt,tag)
        jh=d.get("jump_host",""); cap=d.get("console_ap_host","")
        if cap:
            self._write(self.dev_det,f"Console AP  : {cap}\n","wrn")
            self._write(self.dev_det,f"Console Cmd : {d.get('console_cmd','')}\n","wrn")
        elif jh:
            self._write(self.dev_det,f"Jump Host   : {jh}\n","wrn")
            self._write(self.dev_det,f"Jump User   : {d.get('jump_username','')}\n","wrn")
        else:
            self._write(self.dev_det,"Connection  : Direct SSH\n","inf")

    def _dev_add(self):
        dlg=DeviceDlg(self.root,title="Add Device")
        self.root.wait_window(dlg)
        if dlg.result:
            r=dlg.result; name=r.pop("_name")
            if name in self.devices:
                messagebox.showwarning("Duplicate",f"'{name}' already exists."); return
            self.devices[name]=r; self._dev_refresh()
            self._setbar(f"Device '{name}' added.")
            self._dev_autosave()

    def _dev_edit(self):
        sel=self.dev_lb.curselection()
        if not sel: messagebox.showinfo("No Selection","Select a device to edit."); return
        old=self.dev_lb.get(sel[0]); pf=dict(self.devices[old]); pf["_name"]=old
        dlg=DeviceDlg(self.root,title="Edit Device",prefill=pf)
        self.root.wait_window(dlg)
        if dlg.result:
            r=dlg.result; new=r.pop("_name")
            del self.devices[old]; self.devices[new]=r
            self._dev_refresh(); self._setbar(f"Updated → '{new}'.")
            self._dev_autosave()

    def _dev_rm(self):
        sel=self.dev_lb.curselection()
        if not sel: messagebox.showinfo("No Selection","Select a device to remove."); return
        name=self.dev_lb.get(sel[0])
        if messagebox.askyesno("Confirm",f"Remove '{name}'?"):
            del self.devices[name]; self._dev_refresh()
            self._clr(self.dev_det); self._setbar(f"'{name}' removed.")

    def _dev_autosave(self):
        """Silently persist devices to disk after every add/edit (no popup)."""
        try:
            sk = {"_name"}
            to_save = {k: {kk: vv for kk, vv in v.items() if kk not in sk}
                       for k, v in self.devices.items()}
            enc_save(DEVICES_FILE, to_save)
            self._setbar("Devices auto-saved.")
        except Exception as _e:
            self._setbar(f"Auto-save failed: {_e}")

    def _dev_save(self):
        sk={"_name"}
        to_save={k:{kk:vv for kk,vv in v.items() if kk not in sk}
                  for k,v in self.devices.items()}
        enc_save(DEVICES_FILE,to_save)
        messagebox.showinfo("Saved",f"Devices encrypted → {DEVICES_FILE}")
        self._setbar("Devices saved (encrypted).")

    # ═════════════════════════════════════════════════════════════════════════
    # EXPORTS
    # ═════════════════════════════════════════════════════════════════════════
    def _exp_txt(self):
        if not self.current:
            messagebox.showinfo("No Data","Connect and run commands first."); return
        fn=f"{sn(self.current)}_{STS}.txt"
        if os.path.exists(fn):
            dest=filedialog.asksaveasfilename(defaultextension=".txt",
                initialfile=fn,filetypes=[("Text","*.txt")])
            if dest and dest!=fn: shutil.copy(fn,dest)
            messagebox.showinfo("Exported",f"Saved: {fn}")
        else: messagebox.showinfo("No Log","No session log yet.")

    def _exp_json(self):
        if not self.log: messagebox.showinfo("No Data","Run commands first."); return
        messagebox.showinfo("Exported",f"JSON: {to_json(self.current or 'session',self.log)}")

    def _exp_csv(self):
        if not self.log: messagebox.showinfo("No Data","Run commands first."); return
        messagebox.showinfo("Exported",f"CSV: {to_csv(self.current or 'session',self.log)}")


