import sqlite3, socket, ipaddress, platform, struct
from threading import Event as TEvent

DB_FILE  = "netauto.db"
PDF_DEPS = True   # set False if reportlab not installed

# ─────────────────────────────────────────────────────────────────────────────
# DATABASE  (SQLite — single file, no server needed)
# ─────────────────────────────────────────────────────────────────────────────
def db_conn():
    return sqlite3.connect(DB_FILE, check_same_thread=False)

def db_init():
    with db_conn() as c:
        c.executescript("""
        CREATE TABLE IF NOT EXISTS devices (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT UNIQUE, host TEXT, device_type TEXT,
            username TEXT, password TEXT, port INTEGER DEFAULT 22,
            enable_secret TEXT DEFAULT '', fast_cli INTEGER DEFAULT 0,
            key_file TEXT DEFAULT '', vendor TEXT DEFAULT '',
            model TEXT DEFAULT '', serial TEXT DEFAULT '',
            ios_version TEXT DEFAULT '', location TEXT DEFAULT '',
            site TEXT DEFAULT '', tags TEXT DEFAULT '',
            notes TEXT DEFAULT '', groups TEXT DEFAULT '',
            jump_host TEXT DEFAULT '', jump_username TEXT DEFAULT '',
            jump_password TEXT DEFAULT '', jump_port INTEGER DEFAULT 22,
            jump_device_type TEXT DEFAULT 'cisco_ios',
            console_ap_host TEXT DEFAULT '', console_ap_user TEXT DEFAULT '',
            console_ap_pass TEXT DEFAULT '', console_cmd TEXT DEFAULT 'telnet 0',
            console_dev_pass TEXT DEFAULT '',
            last_connected TEXT DEFAULT '', last_backup TEXT DEFAULT '',
            status TEXT DEFAULT 'unknown', uptime TEXT DEFAULT '',
            mac_address TEXT DEFAULT ''
        );
        CREATE TABLE IF NOT EXISTS backups (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            device TEXT, filepath TEXT, btype TEXT,
            created TEXT, size INTEGER DEFAULT 0
        );
        CREATE TABLE IF NOT EXISTS alerts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            device TEXT, severity TEXT, message TEXT,
            created TEXT, acknowledged INTEGER DEFAULT 0
        );
        CREATE TABLE IF NOT EXISTS logs (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            device TEXT, command TEXT, output TEXT,
            ts TEXT, user TEXT DEFAULT 'local'
        );
        CREATE TABLE IF NOT EXISTS templates (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT UNIQUE, category TEXT, commands TEXT,
            description TEXT DEFAULT '', created TEXT
        );
        CREATE TABLE IF NOT EXISTS settings (
            key TEXT PRIMARY KEY, value TEXT
        );
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT UNIQUE, password_hash TEXT,
            role TEXT DEFAULT 'operator', active INTEGER DEFAULT 1
        );
        CREATE TABLE IF NOT EXISTS compliance_rules (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT, check_type TEXT, expected TEXT,
            severity TEXT DEFAULT 'warning'
        );
        """)
        # Seed default admin user (password: admin)
        import hashlib
        pw = hashlib.sha256(b"admin").hexdigest()
        c.execute("INSERT OR IGNORE INTO users (username,password_hash,role) VALUES (?,?,?)",
                  ("admin", pw, "admin"))
        # Seed default compliance rules
        rules = [
            ("SSH Enabled",        "contains", "transport input ssh",    "critical"),
            ("Password Encryption","contains", "service password-encry", "warning"),
            ("NTP Configured",     "contains", "ntp server",             "warning"),
            ("Banner Configured",  "contains", "banner motd",            "info"),
            ("SNMP Configured",    "contains", "snmp-server community",  "info"),
        ]
        c.executemany(
            "INSERT OR IGNORE INTO compliance_rules (name,check_type,expected,severity) VALUES (?,?,?,?)",
            rules)

def db_save_device(d: dict):
    cols = [k for k in d if k != "_name"]
    vals = [d[k] for k in cols]
    ph   = ",".join("?"*len(cols))
    col_str = ",".join(cols)
    with db_conn() as c:
        c.execute(f"INSERT OR REPLACE INTO devices ({col_str}) VALUES ({ph})", vals)

def db_load_devices() -> list:
    with db_conn() as c:
        c.row_factory = sqlite3.Row
        return [dict(r) for r in c.execute("SELECT * FROM devices ORDER BY name")]

def db_delete_device(name: str):
    with db_conn() as c:
        c.execute("DELETE FROM devices WHERE name=?", (name,))

def db_add_alert(device, severity, message):
    with db_conn() as c:
        c.execute("INSERT INTO alerts (device,severity,message,created) VALUES (?,?,?,?)",
                  (device, severity, message, datetime.now().isoformat()))

def db_get_alerts(ack=False):
    with db_conn() as c:
        c.row_factory = sqlite3.Row
        return [dict(r) for r in c.execute(
            "SELECT * FROM alerts WHERE acknowledged=? ORDER BY created DESC LIMIT 200",
            (1 if ack else 0,))]

def db_ack_alert(aid):
    with db_conn() as c:
        c.execute("UPDATE alerts SET acknowledged=1 WHERE id=?", (aid,))

def db_log_cmd(device, cmd, output, user="local"):
    with db_conn() as c:
        c.execute("INSERT INTO logs (device,command,output,ts,user) VALUES (?,?,?,?,?)",
                  (device, cmd, output[:5000], datetime.now().isoformat(), user))

def db_get_templates():
    with db_conn() as c:
        c.row_factory = sqlite3.Row
        return [dict(r) for r in c.execute("SELECT * FROM templates ORDER BY category,name")]

def db_save_template(name, category, commands, description=""):
    with db_conn() as c:
        c.execute("""INSERT OR REPLACE INTO templates
                     (name,category,commands,description,created)
                     VALUES (?,?,?,?,?)""",
                  (name, category, commands, description, datetime.now().isoformat()))

def db_delete_template(name):
    with db_conn() as c:
        c.execute("DELETE FROM templates WHERE name=?", (name,))

def db_get_setting(key, default=""):
    with db_conn() as c:
        row = c.execute("SELECT value FROM settings WHERE key=?", (key,)).fetchone()
        return row[0] if row else default

def db_set_setting(key, value):
    with db_conn() as c:
        c.execute("INSERT OR REPLACE INTO settings (key,value) VALUES (?,?)", (key, value))

def db_check_user(username, password):
    import hashlib
    pw = hashlib.sha256(password.encode()).hexdigest()
    with db_conn() as c:
        row = c.execute(
            "SELECT role FROM users WHERE username=? AND password_hash=? AND active=1",
            (username, pw)).fetchone()
        return row[0] if row else None

def db_get_users():
    with db_conn() as c:
        c.row_factory = sqlite3.Row
        return [dict(r) for r in c.execute("SELECT id,username,role,active FROM users")]

def db_add_user(username, password, role="operator"):
    import hashlib
    pw = hashlib.sha256(password.encode()).hexdigest()
    with db_conn() as c:
        c.execute("INSERT OR REPLACE INTO users (username,password_hash,role) VALUES (?,?,?)",
                  (username, pw, role))

def db_get_compliance_rules():
    with db_conn() as c:
        c.row_factory = sqlite3.Row
        return [dict(r) for r in c.execute("SELECT * FROM compliance_rules")]


