# LOGIN DIALOG
# ─────────────────────────────────────────────────────────────────────────────
class LoginDlg(tk.Toplevel):
    def __init__(self, parent):
        super().__init__(parent)
        self.title("Login"); self.resizable(False, False)
        self.grab_set(); self.protocol("WM_DELETE_WINDOW", self._cancel)
        self.result = None
        self.configure(bg=TERM_BG)
        tk.Label(self, text="⚡ ShikaNet",
                 font=(FONT_MONO,13,"bold"), bg=TERM_BG, fg=TERM_PUR).pack(pady=(24,4))
        tk.Label(self, text="Please log in to continue",
                 font=(FONT_MONO,9), bg=TERM_BG, fg=TERM_GRY).pack(pady=(0,16))
        f = ttk.Frame(self, padding=(30,0,30,0)); f.pack()
        ttk.Label(f, text="Username", font=(FONT_MONO,9,"bold")).grid(row=0,column=0,sticky=W,pady=4)
        self.u = ttk.Entry(f, font=(FONT_MONO,10), width=22); self.u.grid(row=0,column=1,padx=8,ipady=3)
        self.u.insert(0,"admin")
        ttk.Label(f, text="Password", font=(FONT_MONO,9,"bold")).grid(row=1,column=0,sticky=W,pady=4)
        self.p = ttk.Entry(f, font=(FONT_MONO,10), width=22, show="*")
        self.p.grid(row=1,column=1,padx=8,ipady=3)
        self.err = tk.Label(self, text="", font=(FONT_MONO,8), bg=TERM_BG, fg=TERM_RED)
        self.err.pack(pady=(8,0))
        bf = ttk.Frame(self); bf.pack(pady=(10,20))
        ttk.Button(bf,text="Login",command=self._login,bootstyle="success",width=12).pack(side=LEFT,padx=6)
        ttk.Button(bf,text="Cancel",command=self._cancel,bootstyle="secondary-outline",width=12).pack(side=LEFT,padx=6)
        self.u.focus_set(); self.bind("<Return>", lambda _: self._login())

    def _login(self):
        u=self.u.get().strip(); p=self.p.get()
        role = db_check_user(u, p)
        if role:
            self.result = {"username": u, "role": role}; self.destroy()
        else:
            self.err.config(text="✘ Invalid username or password")
            self.p.delete(0,"end")

    def _cancel(self):
        self.result = None; self.destroy()


# ─────────────────────────────────────────────────────────────────────────────
# NETWORK SCANNER (IP range / subnet ping sweep — no root required)
# ─────────────────────────────────────────────────────────────────────────────
def ping_host(ip: str, timeout: float = 0.5) -> bool:
    """Quick TCP-based reachability check (port 22/23/80). No raw sockets."""
    for port in (22, 23, 80):
        try:
            with socket.create_connection((ip, port), timeout=timeout):
                return True
        except Exception:
            pass
    return False

def scan_range(start_ip: str, end_ip: str,
               progress_cb=None, result_cb=None, stop_event=None):
    """Scan IP range, call result_cb(ip, alive) for each host."""
    try:
        start = int(ipaddress.ip_address(start_ip))
        end   = int(ipaddress.ip_address(end_ip))
    except ValueError:
        return
    total = end - start + 1
    done  = 0
    workers = []
    q = __import__("queue").Queue()

    def check(ip_int):
        ip = str(ipaddress.ip_address(ip_int))
        alive = ping_host(ip)
        q.put((ip, alive))

    import concurrent.futures
    with concurrent.futures.ThreadPoolExecutor(max_workers=50) as ex:
        futs = [ex.submit(check, i) for i in range(start, end+1)]
        for _ in futs:
            ip, alive = q.get()
            done += 1
            if progress_cb:
                progress_cb(int(done/total*100), ip)
            if result_cb and alive:
                result_cb(ip)
            if stop_event and stop_event.is_set():
                break

# ─────────────────────────────────────────────────────────────────────────────
# COMPLIANCE CHECKER
# ─────────────────────────────────────────────────────────────────────────────
def run_compliance(running_config: str) -> list:
    """Check running config against stored rules. Returns list of results."""
    rules   = db_get_compliance_rules()
    results = []
    for r in rules:
        if r["check_type"] == "contains":
            passed = r["expected"].lower() in running_config.lower()
        elif r["check_type"] == "not_contains":
            passed = r["expected"].lower() not in running_config.lower()
        else:
            passed = False
        results.append({
            "rule":     r["name"],
            "passed":   passed,
            "severity": r["severity"],
            "expected": r["expected"],
        })
    return results

# ─────────────────────────────────────────────────────────────────────────────
# EXPORT — HTML + PDF (PDF via reportlab if available)
# ─────────────────────────────────────────────────────────────────────────────
def export_html(device: str, entries: list, notes: str = "") -> str:
    fn = f"{sn(device)}_report_{STS}.html"
    rows = "".join(
        f"<tr><td>{e['timestamp']}</td>"
        f"<td><code>{e['command']}</code></td>"
        f"<td><pre>{e['output'][:800]}</pre></td></tr>"
        for e in entries)
    html = f"""<!DOCTYPE html><html><head>
<title>Network Report — {device}</title>
<style>
body{{font-family:monospace;background:#0d0d17;color:#cdd6f4;margin:24px}}
h1{{color:#cba6f7}} table{{border-collapse:collapse;width:100%}}
th{{background:#1e1e2e;padding:8px;text-align:left}}
td{{border-bottom:1px solid #45475a;padding:6px;vertical-align:top}}
pre{{margin:0;white-space:pre-wrap;font-size:11px}}
.notes{{background:#1e1e2e;padding:12px;border-left:4px solid #f9e2af;margin:12px 0}}
</style></head><body>
<h1>⚡ ShikaNet Report</h1>
<p>Device: <b>{device}</b> &nbsp;|&nbsp; Generated: {datetime.now()}</p>
{"<div class='notes'><b>Notes:</b><br>"+notes+"</div>" if notes else ""}
<table><tr><th>Time</th><th>Command</th><th>Output</th></tr>{rows}</table>
</body></html>"""
    with open(fn, "w", encoding="utf-8") as f:
        f.write(html)
    return fn

def export_pdf(device: str, entries: list, notes: str = "") -> str:
    fn = f"{sn(device)}_report_{STS}.pdf"
    try:
        from reportlab.lib.pagesizes import A4
        from reportlab.lib.styles import getSampleStyleSheet
        from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table
        from reportlab.lib import colors
        doc  = SimpleDocTemplate(fn, pagesize=A4)
        st   = getSampleStyleSheet()
        els  = [Paragraph(f"ShikaNet Report — {device}", st["Title"]),
                Paragraph(f"Generated: {datetime.now()}", st["Normal"]),
                Spacer(1,12)]
        if notes:
            els.append(Paragraph(f"Notes: {notes}", st["Normal"]))
            els.append(Spacer(1,8))
        data = [["Time","Command","Output (truncated)"]]
        for e in entries:
            data.append([e["timestamp"], e["command"], e["output"][:300]])
        t = Table(data, colWidths=[70,150,260])
        t.setStyle([("BACKGROUND",(0,0),(-1,0),colors.HexColor("#1e1e2e")),
                    ("TEXTCOLOR",(0,0),(-1,0),colors.white),
                    ("FONTSIZE",(0,0),(-1,-1),7),
                    ("GRID",(0,0),(-1,-1),0.3,colors.gray)])
        els.append(t)
        doc.build(els)
        return fn
    except ImportError:
        return export_html(device, entries, notes)  # fallback to HTML


