class AppV9(App):
    """Extends App (v8) with all new v9 features."""

    def __init__(self, root, user_info):
        self._current_user  = user_info["username"]
        self._current_role  = user_info["role"]
        self._alert_count   = 0
        self._scan_stop     = TEvent()
        self._snmp_polling  = False
        self._topo_nodes    = {}
        db_init()
        # Load saved theme preference before building UI
        self._saved_theme = db_get_setting("theme", "darkly")
        # Merge DB devices into memory before building
        self._db_devices_loaded = False
        super().__init__(root)

    # ── Override _load_devices to pull from SQLite ────────────────────────
    def _load_devices(self):
        super()._load_devices()
        for row in db_load_devices():
            name = row.pop("name", row.get("id",""))
            row.pop("id", None)
            self.devices[str(name)] = row
        self._db_devices_loaded = True

    # ── Override _build to add extra tabs ─────────────────────────────────
    def _build(self):
        super()._build()
        # Append new tabs to existing notebook
        self._tab_dashboard()    # inserted as first visible tab
        self._tab_discovery()
        self._tab_templates()
        self._tab_compliance()
        self._tab_alerts()
        self._tab_reports()
        self._tab_topology()
        self._tab_firmware()
        self._tab_ai()
        self._tab_plugins()
        self._tab_settings()
        self._tab_users()
        self._tab_help()
        # Update title to show user
        self.root.title(f"{APP_TITLE}  [{self._current_user}  •  {self._current_role}]")
        # Override about to show v9
        self._update_menu_v9()
        # Restore persisted theme after UI is fully built
        _saved = getattr(self, "_saved_theme", "darkly")
        if _saved and _saved != "darkly":
            try:
                ttk.Style().theme_use(_saved)
                self._theme = _saved
            except Exception:
                pass
        # Show first-run getting-started tips when no devices exist
        if not self.devices:
            self.root.after(600, self._show_first_run_hint)
        # Start alert polling
        self.root.after(30000, self._poll_alerts)

    def _update_menu_v9(self):
        pass  # menu already built; new items added via tabs

    # ══════════════════════════════════════════════════════════════════════
    # TAB — DASHBOARD
    # ══════════════════════════════════════════════════════════════════════
    def _tab_dashboard(self):
        f = ttk.Frame(self.nb, padding=(14,10))
        self.nb.insert(0, f, text="  🏠  Dashboard  ")

        # Top stat cards row
        cards = ttk.Frame(f); cards.pack(fill=X, pady=(0,10))
        self._dash_cards = {}
        for label, key, bs in [
            ("Total Devices",  "total",   "primary"),
            ("Online",         "online",  "success"),
            ("Offline",        "offline", "danger"),
            ("Active Alerts",  "alerts",  "warning"),
            ("Last Backup",    "backup",  "info"),
            ("Health Score",   "health",  "success"),
        ]:
            card = ttk.Frame(cards, bootstyle=bs, padding=(12,8))
            card.pack(side=LEFT, expand=True, fill=X, padx=4)
            ttk.Label(card, text=label, font=(FONT_MONO,8), bootstyle=f"{bs}-inverse").pack()
            val = ttk.Label(card, text="—", font=(FONT_MONO,16,"bold"), bootstyle=f"{bs}-inverse")
            val.pack()
            self._dash_cards[key] = val

        # Quick actions row
        qa = ttk.Frame(f); qa.pack(fill=X, pady=(0,10))
        for txt, cmd, bs in [
            ("⚡ Connect",         self._connect,          "success"),
            ("❤  Health Check",   self._health_check,     "danger"),
            ("💾 Quick Backup",    self._quick_bak,        "info"),
            ("▶▶ Run All Show",   self._run_all_show,     "warning"),
            ("🔍 Discover",        lambda: self.nb.select(self.nb.index("end")-10), "secondary"),
            ("📋 Compliance",      lambda: self.nb.select(self.nb.index("end")-8),  "primary"),
        ]:
            b = ttk.Button(qa, text=txt, command=cmd, bootstyle=bs, width=18)
            b.pack(side=LEFT, padx=3)

        ttk.Separator(f, orient=HORIZONTAL).pack(fill=X, pady=(0,8))

        # Two-column layout: live output + alerts
        cols = ttk.Frame(f); cols.pack(fill=BOTH, expand=True)

        # Left: recent activity
        lf = ttk.Frame(cols, padding=(0,0,8,0)); lf.pack(side=LEFT, fill=BOTH, expand=True)
        ttk.Label(lf, text="RECENT ACTIVITY", font=(FONT_MONO,8,"bold"),
                  bootstyle="secondary").pack(anchor=W, pady=(0,4))
        self.dash_activity = self._mkbox(lf)

        # Right: live alerts
        rf = ttk.Frame(cols, padding=(8,0,0,0), width=320); rf.pack(side=LEFT, fill=Y)
        rf.pack_propagate(False)
        ttk.Label(rf, text="ACTIVE ALERTS", font=(FONT_MONO,8,"bold"),
                  bootstyle="warning").pack(anchor=W, pady=(0,4))
        self.dash_alerts_box = self._mkbox(rf)

        # Refresh button
        br = ttk.Frame(f); br.pack(fill=X, pady=(6,0))
        ttk.Button(br, text="🔄 Refresh Dashboard",
                   command=self._refresh_dashboard,
                   bootstyle="secondary-outline").pack(side=LEFT, padx=2)
        ttk.Button(br, text="📡 Ping All Devices",
                   command=self._ping_all_status,
                   bootstyle="info-outline").pack(side=LEFT, padx=2)

        self.root.after(1000, self._refresh_dashboard)

    def _show_first_run_hint(self):
        """Show getting-started tips in the dashboard activity log on first launch."""
        tips = [
            ("hdr", "\n  Welcome to ShikaNet v9!\n"),
            ("inf", "  No devices are configured yet — here is how to get started:\n\n"),
            ("ok",  "  1.  Devices → ➕ Add Device  to add a router or switch.\n"),
            ("ok",  "  2.  Devices → 📥 Import CSV/JSON  to bulk-import from a file.\n"),
            ("ok",  "  3.  Network → Discovery  to scan a subnet for live hosts.\n"),
            ("wrn", "\n  Keyboard shortcuts:\n"),
            ("div", "    F5  Connect/Disconnect        Ctrl+R  Run All Show\n"),
            ("div", "    Ctrl+H  Health Check           Ctrl+K  Clear Output\n"),
            ("div", "    Ctrl+B  Quick Backup           Ctrl+S  Save Config\n\n"),
        ]
        if hasattr(self, "dash_activity"):
            for tag, text in tips:
                self._write(self.dash_activity, text, tag)

    def _refresh_dashboard(self):
        total   = len(self.devices)
        online  = sum(1 for d in self.devices.values()
                      if d.get("status","") == "online")
        offline = total - online
        alerts  = len(db_get_alerts())
        # Last backup
        baks = sorted([f for f in os.listdir(BACKUP_DIR)
                       if f.endswith(".txt")], reverse=True) if os.path.isdir(BACKUP_DIR) else []
        last_bak = baks[0][:16] if baks else "Never"
        # Health score (simple: % online devices, penalise open alerts)
        health = max(0, int((online/total*100 if total else 100) - min(alerts*5,40)))

        self._dash_cards["total"].config( text=str(total))
        self._dash_cards["online"].config(text=str(online))
        self._dash_cards["offline"].config(text=str(offline))
        self._dash_cards["alerts"].config(text=str(alerts))
        self._dash_cards["backup"].config(text=last_bak)
        self._dash_cards["health"].config(text=f"{health}%")

        # Refresh alert box
        self._clr(self.dash_alerts_box)
        for a in db_get_alerts()[:20]:
            sev = a.get("severity","info")
            tag = "err" if sev=="critical" else "wrn" if sev=="warning" else "inf"
            self._write(self.dash_alerts_box,
                        f"[{a['created'][11:19]}] {a['device']}: {a['message']}\n", tag)
        if not db_get_alerts():
            self._write(self.dash_alerts_box, "No active alerts ✔\n", "ok")

    def _ping_all_status(self):
        self._write(self.dash_activity, "\n▶ Pinging all devices…\n", "wrn")
        def work():
            for name, d in self.devices.items():
                host = d.get("host","")
                alive = ping_host(host, timeout=1.0) if host else False
                self.devices[name]["status"] = "online" if alive else "offline"
                tag = "ok" if alive else "err"
                sym = "✔" if alive else "✘"
                self.root.after(0, lambda n=name, s=sym, t=tag:
                    self._write(self.dash_activity, f"  {s} {n}\n", t))
            self.root.after(0, lambda: (
                self._write(self.dash_activity, "Done.\n", "div"),
                self._refresh_dashboard()))
        threading.Thread(target=work, daemon=True).start()

    def _poll_alerts(self):
        """Background alert check every 30s if connected."""
        if self.conn and self.current:
            def work():
                try:
                    cpu = self._send("show processes cpu | include CPU")
                    if "CPU utilization" in cpu:
                        pct = re.search(r"five seconds: (\d+)", cpu)
                        if pct and int(pct.group(1)) > 80:
                            db_add_alert(self.current, "warning",
                                         f"High CPU: {pct.group(1)}%")
                            self.root.after(0, self._refresh_dashboard)
                except Exception:
                    pass
            threading.Thread(target=work, daemon=True).start()
        self.root.after(30000, self._poll_alerts)

