    def _start_disc(self):
        self._scan_stop.clear()
        self._discovered_hosts = []
        self._clr(self.disc_out)
        start = self.disc_start.get().strip()
        end   = self.disc_end.get().strip()
        self._write(self.disc_out, f"Scanning {start} → {end}…\n", "wrn")

        def on_progress(pct, ip):
            self.root.after(0, lambda: (
                self.disc_pb.configure(value=pct),
                self.disc_status.config(text=f"Scanning {ip}…")))

        def on_found(ip):
            self._discovered_hosts.append(ip)
            self.root.after(0, lambda:
                self._write(self.disc_out, f"  ✔ {ip} — alive\n", "ok"))

        def run():
            scan_range(start, end, on_progress, on_found, self._scan_stop)
            self.root.after(0, lambda: (
                self.disc_pb.configure(value=100),
                self.disc_status.config(text=f"Done. {len(self._discovered_hosts)} hosts found."),
                self._write(self.disc_out,
                            f"\nScan complete: {len(self._discovered_hosts)} live hosts.\n","ok")))
        threading.Thread(target=run, daemon=True).start()

    def _disc_protocol(self, proto):
        if not self._req(): return
        cmd = f"show {proto} neighbors detail"
        self._write(self.disc_out, f"\n▶ {cmd}\n", "hdr")
        def work():
            out = self._send(cmd, timeout=30)
            self.root.after(0, lambda: self._write(self.disc_out, out+"\n"))
        threading.Thread(target=work, daemon=True).start()

    def _add_discovered(self):
        added = 0
        for ip in self._discovered_hosts:
            name = f"Discovered-{ip}"
            if name not in self.devices:
                self.devices[name] = {
                    "host":ip,"device_type":"cisco_ios","username":"admin",
                    "password":"","port":22,"fast_cli":False,"key_file":"",
                    "jump_host":"","jump_username":"","jump_password":"",
                    "jump_port":22,"jump_device_type":"cisco_ios",
                    "console_ap_host":"","console_ap_user":"","console_ap_pass":"",
                    "console_cmd":"telnet 0","console_dev_pass":"",
                    "vendor":"","model":"","serial":"","location":"",
                    "site":"","tags":"","notes":"","groups":"","enable_secret":"",
                    "status":"online",
                }; added += 1
        self._dev_refresh()
        messagebox.showinfo("Added", f"Added {added} discovered devices.\nEdit credentials in Device Manager.")

    def _import_csv(self):
        fn = filedialog.askopenfilename(
            title="Import Devices (CSV or JSON)",
            filetypes=[("CSV","*.csv"),("JSON","*.json"),("All","*.*")])
        if not fn: return
        added = 0; errors = []
        try:
            # ── JSON branch ───────────────────────────────────────────────
            if fn.lower().endswith(".json"):
                with open(fn, encoding="utf-8") as f:
                    raw = json.load(f)
                if isinstance(raw, dict):
                    rows = [dict(v, name=k) for k, v in raw.items()]
                elif isinstance(raw, list):
                    rows = raw
                else:
                    raise ValueError("JSON must be a list or dict of device objects")
                for row in rows:
                    name = row.get("name","").strip()
                    host = row.get("host","").strip()
                    if not name or not host:
                        errors.append(f"Row missing name/host: {row}"); continue
                    self.devices[name] = {
                        "host": host,
                        "device_type": row.get("device_type","cisco_ios"),
                        "username": row.get("username","admin"),
                        "password": row.get("password",""),
                        "port": int(row.get("port", 22)),
                        "fast_cli":False,"key_file":"",
                        "jump_host":"","jump_username":"","jump_password":"",
                        "jump_port":22,"jump_device_type":"cisco_ios",
                        "console_ap_host":"","console_ap_user":"","console_ap_pass":"",
                        "console_cmd":"telnet 0","console_dev_pass":"",
                        "vendor":row.get("vendor",""),"model":row.get("model",""),
                        "serial":row.get("serial",""),"location":row.get("location",""),
                        "site":row.get("site",""),"tags":row.get("tags",""),
                        "notes":row.get("notes",""),"groups":row.get("groups",""),
                        "enable_secret":row.get("enable_secret",""),"status":"unknown",
                    }; added += 1
                self._dev_refresh()
                msg = f"Imported {added} device(s) from JSON."
                if errors: msg += f"\n{len(errors)} row(s) skipped."
                messagebox.showinfo("Import Complete", msg)
                return
            # ── CSV branch ────────────────────────────────────────────────
            with open(fn, encoding="utf-8") as f:
                reader = csv.DictReader(f)
                for row in reader:
                    name = row.get("name","").strip()
                    host = row.get("host","").strip()
                    if not name or not host:
                        errors.append(f"Row missing name/host: {row}"); continue
                    self.devices[name] = {
                        "host":host,
                        "device_type":row.get("device_type","cisco_ios"),
                        "username":row.get("username","admin"),
                        "password":row.get("password",""),
                        "port":int(row.get("port",22)),
                        "fast_cli":False,"key_file":"",
                        "jump_host":"","jump_username":"","jump_password":"",
                        "jump_port":22,"jump_device_type":"cisco_ios",
                        "console_ap_host":"","console_ap_user":"","console_ap_pass":"",
                        "console_cmd":"telnet 0","console_dev_pass":"",
                        "vendor":row.get("vendor",""),"model":row.get("model",""),
                        "serial":row.get("serial",""),"location":row.get("location",""),
                        "site":row.get("site",""),"tags":row.get("tags",""),
                        "notes":row.get("notes",""),"groups":row.get("groups",""),
                        "enable_secret":row.get("enable_secret",""),"status":"unknown",
                    }; added += 1
            self._dev_refresh()
            msg = f"Imported {added} device(s)."
            if errors: msg += f"\n{len(errors)} row(s) skipped."
            messagebox.showinfo("Import Complete", msg)
        except Exception as e:
            messagebox.showerror("Import Error", str(e))


