    # TAB — FIRMWARE AUDIT
    # ══════════════════════════════════════════════════════════════════════
    def _tab_firmware(self):
        f = ttk.Frame(self.nb); self.nb.add(f, text="  🔧  Firmware  ")
        left = ttk.Frame(f,padding=(14,12,8,12),width=300)
        left.pack(side=LEFT,fill=Y); left.pack_propagate(False)
        self._shdr(left,"FIRMWARE & IOS AUDIT")
        ttk.Label(left,
                  text="Detects IOS versions across all\ndevices and flags outdated ones.",
                  font=(FONT_MONO,8),bootstyle="secondary",justify=LEFT).pack(anchor=W,pady=(0,10))
        for t,c,bs in [("🔍 Audit Current Device",  self._fw_audit_one, "success"),
                        ("🌐 Audit All Devices",      self._fw_audit_all, "warning"),
                        ("📤 Export Firmware Report", self._fw_export,    "info-outline")]:
            ttk.Button(left,text=t,command=c,bootstyle=bs).pack(fill=X,pady=3,padx=2)
        ttk.Separator(left,orient=HORIZONTAL).pack(fill=X,pady=(10,8))
        ttk.Label(left,text="IOS versions flagged as EOL:",
                  font=(FONT_MONO,8,"bold"),bootstyle="warning").pack(anchor=W,pady=(0,4))
        ttk.Label(left,
                  text="12.x, 15.0, 15.1 (partial)\n(add more in compliance rules)",
                  font=(FONT_MONO,7),bootstyle="secondary").pack(anchor=W)
        self._fw_results = []
        ttk.Separator(f,orient=VERTICAL).pack(side=LEFT,fill=Y,padx=4)
        r=ttk.Frame(f,padding=(8,12)); r.pack(side=LEFT,fill=BOTH,expand=True)
        self._hdr(r,"FIRMWARE AUDIT REPORT")
        self.fw_out = self._mkbox(r)
        self._search(r,self.fw_out)

    def _fw_audit_one(self):
        if not self._req(): return
        def work():
            out = self._send("show version")
            ver = re.search(r"Cisco IOS.+?Version\s+(\S+)", out)
            model= re.search(r"cisco\s+(\S+).*processor", out, re.I)
            v = ver.group(1) if ver else "Unknown"
            m = model.group(1) if model else "Unknown"
            eol = v.startswith(("12.","15.0","15.1"))
            tag = "err" if eol else "ok"
            self._fw_results.append({"device":self.current,"version":v,"model":m,"eol":eol})
            self.root.after(0,lambda:(
                self._write(self.fw_out,f"Device : {self.current}\n","hdr"),
                self._write(self.fw_out,f"Model  : {m}\n","inf"),
                self._write(self.fw_out,f"Version: {v}\n",tag),
                self._write(self.fw_out,f"Status : {'⚠ EOL — consider upgrade' if eol else '✔ Supported'}\n",tag),
                self._write(self.fw_out,"─"*50+"\n","div")))
        threading.Thread(target=work,daemon=True).start()

    def _fw_audit_all(self):
        self._write(self.fw_out,"\n▶ Auditing all devices…\n","wrn")
        self._fw_results = []
        JK={"jump_host","jump_username","jump_password","jump_port","jump_device_type",
            "console_ap_host","console_ap_user","console_ap_pass","console_cmd","console_dev_pass"}
        def work():
            for name,d in self.devices.items():
                cfg={k:v for k,v in d.items() if k not in JK}
                if not cfg.get("key_file"): cfg.pop("key_file",None)
                try:
                    c=ConnectHandler(**cfg)
                    out=c.send_command("show version",expect_string=r"#",
                                       read_timeout=30,strip_prompt=True,strip_command=True)
                    c.disconnect()
                    ver=re.search(r"Version\s+(\S+)",out)
                    v=ver.group(1) if ver else "Unknown"
                    eol=v.startswith(("12.","15.0","15.1"))
                    self._fw_results.append({"device":name,"version":v,"eol":eol})
                    tag="err" if eol else "ok"
                    icon="⚠" if eol else "✔"
                    self.root.after(0,lambda n=name,ver=v,t=tag,i=icon:
                        self._write(self.fw_out,f"  {i} {n}: IOS {ver}\n",t))
                except Exception as e:
                    self.root.after(0,lambda n=name,err=str(e):
                        self._write(self.fw_out,f"  ✘ {n}: {err}\n","err"))
            self.root.after(0,lambda:self._write(self.fw_out,"\n✔ Firmware audit complete.\n","ok"))
        threading.Thread(target=work,daemon=True).start()

    def _fw_export(self):
        if not self._fw_results:
            messagebox.showinfo("No Data","Run firmware audit first."); return
        fn=filedialog.asksaveasfilename(defaultextension=".csv",
                                        initialfile="firmware_audit.csv",
                                        filetypes=[("CSV","*.csv")])
        if not fn: return
        with open(fn,"w",newline="",encoding="utf-8") as f:
            w=csv.writer(f)
            w.writerow(["Device","IOS Version","Model","EOL"])
            for r in self._fw_results:
                w.writerow([r["device"],r.get("version",""),r.get("model",""),r.get("eol","")])
        messagebox.showinfo("Exported",f"Saved: {fn}")


