        chat_f = ttk.Frame(f, padding=(8,8)); chat_f.pack(fill=BOTH, expand=True)
        self._hdr(chat_f, "CONVERSATION")
        self.ai_out = self._mkbox(chat_f)

        # Input row
        inp_f = ttk.Frame(f, padding=(8,6)); inp_f.pack(fill=X)
