    def _ai_save_key(self):
        key = self.ai_key.get().strip()
        if key:
            db_set_setting("anthropic_api_key", key)
            messagebox.showinfo("Saved", "API key saved (encrypted in database).")

    def _ai_call(self, prompt: str):
        """Call Anthropic API and return response text."""
        key = self.ai_key.get().strip() or db_get_setting("anthropic_api_key","")
        if not key:
            return "⚠ No API key set. Enter your Anthropic API key above."
        import urllib.request, urllib.error
        payload = json.dumps({
            "model": "claude-sonnet-4-6",
            "max_tokens": 1024,
            "messages": [{"role":"user","content": prompt}]
        }).encode()
        req = urllib.request.Request(
            "https://api.anthropic.com/v1/messages",
            data=payload,
            headers={
                "Content-Type":    "application/json",
                "x-api-key":       key,
                "anthropic-version":"2023-06-01",
            },
            method="POST"
        )
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                data = json.loads(resp.read().decode())
                return data["content"][0]["text"]
        except urllib.error.HTTPError as e:
            body = e.read().decode()
            return f"API Error {e.code}: {body[:300]}"
        except Exception as e:
            return f"Error: {e}"

    def _ai_ask(self, prompt: str):
        self._write(self.ai_out, f"\n👤 {prompt[:120]}\n", "hdr")
        self._write(self.ai_out, "🤖 Thinking…\n", "wrn")
        def work():
            resp = self._ai_call(prompt)
            self.root.after(0, lambda: (
                self._clr_last_line(self.ai_out),
                self._write(self.ai_out, f"🤖 {resp}\n\n", "ok")))
        threading.Thread(target=work, daemon=True).start()

    def _clr_last_line(self, box):
        box.configure(state="normal")
        box.delete("end-2l", "end-1c")
        box.configure(state="disabled")

    def _ai_chat(self):
        q = self.ai_input.get().strip()
        if not q: return
        self.ai_input.delete(0,"end")
        context = ""
        if self.log:
            last = self.log[-1]
            context = f"Last command: {last['command']}\nOutput (truncated):\n{last['output'][:800]}\n\n"
        device_ctx = f"Device: {self.current or 'none'}, Type: {self.devices.get(self.current,{}).get('device_type','unknown')}\n" if self.current else ""
        self._ai_ask(f"{device_ctx}{context}User question: {q}")

    def _ai_explain_last(self):
        if not self.log:
            self._write(self.ai_out, "No commands run yet.\n", "wrn"); return
        last = self.log[-1]
        self._ai_ask(
            f"You are a network engineer assistant. Explain the following Cisco IOS command output "
            f"in plain English. Be concise and highlight anything unusual.\n\n"
            f"Command: {last['command']}\nOutput:\n{last['output'][:1500]}")

    def _ai_suggest_fix(self):
        if not self.log:
            self._write(self.ai_out, "No output to analyse.\n", "wrn"); return
        last = self.log[-1]
        self._ai_ask(
            f"You are a Cisco network engineer. Analyse this command output for errors, "
            f"warnings or issues, then suggest specific troubleshooting steps.\n\n"
            f"Command: {last['command']}\nOutput:\n{last['output'][:1500]}")

    def _ai_gen_config(self):
        desc = self.ai_input.get().strip()
        if not desc:
            self._write(self.ai_out,
                        "Type a description in the input box (e.g. 'configure OSPF area 0 on Gi0/0 with network 10.0.0.0/8') then click Generate Config.\n","wrn")
            return
        self.ai_input.delete(0,"end")
        dev_type = self.devices.get(self.current,{}).get("device_type","cisco_ios") if self.current else "cisco_ios"
        self._ai_ask(
            f"Generate Cisco IOS CLI configuration commands for: {desc}\n"
            f"Device type: {dev_type}\n"
            f"Return ONLY the CLI commands, no explanation, ready to paste into a terminal.")

    def _ai_health_summary(self):
        if not self._req(): return
        self._write(self.ai_out, "Collecting health data…\n", "wrn")
        def work():
            outputs = {}
            for cmd in ["show version","show ip interface brief","show processes cpu","show logging"]:
                outputs[cmd] = self._send(cmd)
            combined = "\n\n".join(f"=== {cmd} ===\n{out[:600]}" for cmd,out in outputs.items())
            prompt = (f"You are a network engineer. Summarise the health of this Cisco device "
                      f"in 5-8 bullet points. Flag any issues.\n\nDevice: {self.current}\n\n{combined}")
            resp = self._ai_call(prompt)
            self.root.after(0, lambda:(
                self._write(self.ai_out,f"\n🤖 Health Summary for {self.current}:\n{resp}\n\n","ok")))
        threading.Thread(target=work, daemon=True).start()

    def _ai_review_config(self):
        if not self._req(): return
        self._write(self.ai_out, "Pulling running config for review…\n","wrn")
        def work():
            cfg = self._send("show running-config", timeout=90)
            prompt = (f"Review this Cisco IOS running configuration. "
                      f"List security issues, misconfigurations, and best-practice violations. "
                      f"Be specific with line numbers or config sections.\n\n{cfg[:3000]}")
            resp = self._ai_call(prompt)
            self.root.after(0, lambda:
                self._write(self.ai_out,f"\n🤖 Config Review:\n{resp}\n\n","ok"))
        threading.Thread(target=work, daemon=True).start()

