    def _help_show(self, category):
        text = self._help_sections.get(category, "No content for this category.")
        self._clr(self.help_out)
        self._write(self.help_out, text + "\n", "inf")

    # ══════════════════════════════════════════════════════════════════════
    # OVERRIDE _dev_save to also persist to SQLite
    # ══════════════════════════════════════════════════════════════════════
    def _dev_save(self):
        super()._dev_save()
        for name, d in self.devices.items():
            row = dict(d); row["name"] = name
            try: db_save_device(row)
            except Exception: pass
        self._setbar("Devices saved (encrypted file + SQLite database).")

    # ══════════════════════════════════════════════════════════════════════
    # OVERRIDE _on_output to also log to SQLite
    # ══════════════════════════════════════════════════════════════════════
    def _on_out(self, cmd, out, box):
        super()._on_out(cmd, out, box)
        if self.current:
            db_log_cmd(self.current, cmd, out, self._current_user)


